 void clockAt(Instant now,ZoneId zone){when(reportingClock.instant()).thenReturn(now);when(reportingClock.getZone()).thenReturn(zone);when(reportingClock.withZone(any())).thenAnswer(inv->Clock.fixed(now,inv.getArgument(0)));}
 UUID pricedOrder(String label,String amount,Instant event,Instant created,String state)throws Exception{
  User customer=extra(label+"-buyer",buyer);Product p=course(owner,amount);UUID id=orderId(checkout("SETUP",label,customer,List.of(p.getId()),label,201));simulate("SETUP",id,state.equals("REFUNDED")?"PAID":state,200);if(state.equals("REFUNDED"))simulate("SETUP",id,"REFUNDED",200);
  jdbc.update("update commerce_orders set created_at=?,expires_at=?,paid_at=?,failed_at=?,refunded_at=? where id=?",Timestamp.from(created),Timestamp.from(event.plusSeconds(3600)),state.equals("FAILED")?null:Timestamp.from(state.equals("REFUNDED")?event.minusSeconds(60):event),state.equals("FAILED")?Timestamp.from(event):null,state.equals("REFUNDED")?Timestamp.from(event):null,id);
  jdbc.update("update product_entitlements set created_at=? where user_id=?",Timestamp.from(state.equals("REFUNDED")?event.minusSeconds(60):event),customer.getUserId());return id;
 }
 long seriesSum(JsonNode n,String field){long total=0;for(JsonNode p:n.path("performance").path("series"))total+=p.path(field).asLong();return total;}
 void dailyOrWeekly(String period,String startValue,int days,int count)throws Exception{
  clockAt(Instant.parse("2026-10-03T00:30:00Z"),ZoneId.of("America/Los_Angeles"));Instant start=Instant.parse(startValue),end=Instant.parse("2026-10-04T00:00:00Z");
  UUID a=pricedOrder(period+"-start","1.00",start,start.minusSeconds(60),"PAID");UUID b=pricedOrder(period+"-last","2.00",end.minusNanos(1000),end.minusSeconds(120),"PAID");
  pricedOrder(period+"-before","4.00",start.minusNanos(1000),start.minusSeconds(120),"PAID");pricedOrder(period+"-end","8.00",end,end.minusSeconds(120),"PAID");pricedOrder(period+"-previous-start","16.00",start.minusSeconds(days*86400L),start.minusSeconds(days*86400L+60),"PAID");
  JsonNode n=read("ANALYTICS-002",period+"-utc-buckets","/api/creator/analytics/overview?period="+period,owner,200);JsonNode series=n.path("performance").path("series");assertEquals(count,series.size());assertEquals(300,seriesSum(n,"revenue"));assertEquals(2,seriesSum(n,"orders"));assertEquals(2,seriesSum(n,"customers"));assertEquals(100,series.get(0).path("revenue").asLong());assertEquals(200,series.get(count-1).path("revenue").asLong());
  for(int i=1;i<count-1;i++){assertEquals(0,series.get(i).path("revenue").asLong());assertEquals(0,series.get(i).path("orders").asLong());assertEquals(0,series.get(i).path("customers").asLong());}
  assertEquals(series,n.path("customerGrowth").path("series"));assertEquals(5,n.path("customerGrowth").path("summary").path("totalCustomers").asInt());assertEquals(2,n.path("customerGrowth").path("summary").path("newCustomers").asInt());assertTrue(reportMetric(n,"Revenue").equals("EUR 3"));assertEquals("2",reportMetric(n,"Orders"));assertEquals(-85.0,n.path("performance").path("revenueDelta").asDouble());assertEquals(0.0,n.path("performance").path("orderDelta").asDouble());
  if(days!=90){for(int i=0;i<count;i++)assertEquals(start.plusSeconds(i*86400L).atZone(ZoneOffset.UTC).format(java.time.format.DateTimeFormatter.ofPattern("MMM d",Locale.ENGLISH)),series.get(i).path("label").asText());}
  else{
   for(int i=0;i<13;i++)assertEquals("Week "+(i+1),series.get(i).path("label").asText());
   // Events immediately before and exactly at every 7-day split establish assignment; the last window is only6days.
   for(int i=1;i<=12;i++){Instant split=start.plusSeconds(i*7*86400L);pricedOrder("week-before-"+i,"1.00",split.minusNanos(1000),split.minusSeconds(120),"PAID");pricedOrder("week-at-"+i,"1.00",split,split.minusSeconds(60),"PAID");}
   JsonNode filled=read("ANALYTICS-002","90d-internal-week-boundaries","/api/creator/analytics/overview?period=90d",owner,200);assertEquals(2700,seriesSum(filled,"revenue"));assertEquals(26,seriesSum(filled,"orders"));for(int i=0;i<13;i++)assertEquals(i==0?200:i==12?300:200,filled.path("performance").path("series").get(i).path("revenue").asLong());
  }
  JsonNode sales=read("SALES-001",period+"-utc-event-window","/api/creator/sales/summary?period="+period,owner,200);assertTrue(reportMetric(sales,"Revenue").equals(days==90?"EUR 27":"EUR 3"));
  if(days!=90){assertEquals("2",reportMetric(sales,"Orders"));assertEquals(0.0,n.path("performance").path("orderDelta").asDouble());}
  JsonNode ledger=read("SALES-002",period+"-created-at-not-paid-at","/api/creator/orders?period="+period+"&pageSize=100",owner,200);assertFalse(contentIds(ledger).contains(a.toString()));assertTrue(contentIds(ledger).contains(b.toString()));
 }
 @Test void analytics002SevenUtc(){try{dailyOrWeekly("7d","2026-09-27T00:00:00Z",7,7);}catch(Exception e){throw new RuntimeException(e);}}
 @Test void analytics002ThirtyUtc(){try{dailyOrWeekly("30d","2026-09-04T00:00:00Z",30,30);}catch(Exception e){throw new RuntimeException(e);}}
 @Test void analytics002NinetyUtc(){try{dailyOrWeekly("90d","2026-07-06T00:00:00Z",90,13);}catch(Exception e){throw new RuntimeException(e);}}
 @Test void sales001TodayEventBoundaries()throws Exception{
  clockAt(Instant.parse("2026-10-03T00:30:00Z"),ZoneId.of("America/Los_Angeles"));Instant start=Instant.parse("2026-10-03T00:00:00Z"),end=Instant.parse("2026-10-04T00:00:00Z");
  for(String state:List.of("PAID","REFUNDED","FAILED"))for(int i=0;i<4;i++){Instant at=List.of(start.minusNanos(1000),start,end.minusNanos(1000),end).get(i);pricedOrder("today-"+state+i,"1.00",at,at.minusSeconds(120),state);}
  JsonNode summary=read("SALES-001","today-event-timestamps-utc","/api/creator/sales/summary?period=today",owner,200);assertTrue(reportMetric(summary,"Revenue").equals("EUR 2"));assertEquals("2",reportMetric(summary,"Orders"));assertTrue(reportMetric(summary,"Refunds").equals("EUR 2"));assertEquals("2",reportMetric(summary,"Failed payments"));
  assertEquals(12,orders.count());
 }
 @Test void sales004TiesAndSnapshotMutation()throws Exception{
  Product a=course(owner,"12.25"),b=course(owner,"4.00");String oldA=a.getName(),oldB=b.getName();UUID one=orderId(checkout("SETUP","snapshot-one",buyer,List.of(a.getId(),b.getId()),"snapshot-one",201));simulate("SETUP",one,"PAID",200);
  User other=extra("snapshot-second-buyer",buyer);UUID two=orderId(checkout("SETUP","snapshot-two",other,List.of(a.getId(),b.getId()),"snapshot-two",201));simulate("SETUP",two,"PAID",200);
  jdbc.update("update commerce_orders set created_at=?,paid_at=? where id in (?,?)",Timestamp.from(fixed.minusSeconds(600)),Timestamp.from(fixed.minusSeconds(300)),one,two);
  a.setName("QA Changed Product title");a.setPrice(new BigDecimal("99.99"));products.saveAndFlush(a);b.setName("QA Changed second title");b.setPrice(new BigDecimal("0.01"));products.saveAndFlush(b);
  List<String> expected=List.of(one.toString(),two.toString()).stream().sorted(Comparator.comparing(UUID::fromString)).toList();
