  Product a=course(owner,"3.00"),b=course(owner,"3.00"),noSales=course(owner,"7.00");UUID id=orderId(checkout("SETUP","rank-multi",buyer,List.of(a.getId(),b.getId()),"rank-multi",201));simulate("SETUP",id,"PAID",200);pricedOrder("rank-refund","99.00",fixed.minusSeconds(30),fixed.minusSeconds(90),"REFUNDED");
  JsonNode n=read("ANALYTICS-004","tied-multi-item-ranking","/api/creator/analytics/overview",owner,200);assertEquals(2,n.path("products").size());Set<String> ids=new HashSet<>();for(JsonNode p:n.path("products")){ids.add(p.path("id").asText());assertEquals(300,p.path("revenueCents").asLong());assertEquals(1,p.path("orders").asInt());assertEquals(50.0,p.path("share").asDouble());}assertEquals(Set.of(a.getId().toString(),b.getId().toString()),ids);assertEquals("1",reportMetric(n,"Orders"));assertTrue(reportMetric(n,"Revenue").equals("EUR 6"));
