import React, { useEffect, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import MultiStepProgressBar from './multi-step-progress-bar/multi-step-progress-bar.component';
import StepOne from './step-one/step-one.component';
import StepTwo from './step-two/step-two.component';
import StepThree from './step-three/step-three.component';
import StepFour from './step-four/step-four.component';
import StepFive from './step-five/step-five.component';
import { Button } from '@shared/ui';
import {
  SocialMediaLink,
  UpdateUserRequest,
  AppDispatch,
} from 'core/api/models';
import { selectAuthUser, updateUserDetails } from 'core/store/auth-store';

import './multi-step-form.styles.scss';

export interface MultiStepFormData {
  profileImage: string;
  title: string;
  bio: string;
  website: string;
  tagline: string;
  city: string;
  country: string;
  lat: string;
  long: string;
}

const MultiStepForm: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const [step, setStep] = useState(1);
  const [socialLinks, setSocialLinks] = useState<SocialMediaLink[]>([]);

  const nextStep = () => setStep((prev) => prev + 1);
  const prevStep = () => setStep((prev) => prev - 1);

  const methods = useForm<MultiStepFormData>({
    defaultValues: {
      title: '',
      bio: '',
      website: '',
      city: '',
      country: '',
      lat: '',
      long: '',
      tagline: '',
    },
    mode: 'onTouched',
  });

  useEffect(() => {
    if (user) {
      methods.reset({
        title: user.title,
        bio: user.bio,
        website: user.website,
        city: user.city,
        country: user.country,
        lat: user.lat,
        long: user.long,
        tagline: user.taglineMission,
      });
    }
  }, [user, methods]);

  const onStepValid = (data: MultiStepFormData) => {
    if (step === 1) {
      nextStep();
      return;
    }

    const userDetails: UpdateUserRequest = {
      userId: user!.id!,
      title: data.title,
      bio: data.bio,
      website: data.website,
      city: data.city,
      country: data.country,
      taglineMission: data.tagline,
      socialLinks: socialLinks,
    };

    console.log('[UPDATE USER DETAILS] userDetails', userDetails);
    // Save partial data to Redux or back-end
    dispatch(updateUserDetails(userDetails));
    nextStep();
  };

  return (
    <div className="multi-step-container">
      <MultiStepProgressBar step={step} totalSteps={5} />
      <FormProvider {...methods}>
        <div className="step-container">
          {step === 1 && (
            <>
              <h1 className="step-header">
                Welcome, {user?.firstName} {user?.lastName}...
              </h1>
              <div className="step-content">
                <StepOne />
              </div>
            </>
          )}
          {step === 2 && (
            <>
              <h1 className="step-header">Basic Profile</h1>
              <div className="step-content">
                <StepTwo />
              </div>
            </>
          )}
          {step === 3 && (
            <>
              <h1 className="step-header">About You</h1>
              <div className="step-content">
                <StepThree />
              </div>
            </>
          )}
          {step === 4 && (
            <>
              <h1 className="step-header">Additional information</h1>
              <div className="step-content">
                <StepFour
                  onSocialMediaChange={(links) => setSocialLinks(links)}
                />
              </div>
            </>
          )}
          {step === 5 && (
            <div className="step-content">
              <StepFive />
            </div>
          )}
        </div>
        <div className="step-action-buttons">
          <Button
            type="button"
            variant="neutral"
            onClick={() => navigate('/app')}
          >
            Skip
          </Button>
          {step !== 1 && (
            <Button type="button" variant="primary" onClick={prevStep}>
              Back
            </Button>
          )}
          {step !== 5 && (
            <Button
              type="button"
              variant="primary"
              onClick={methods.handleSubmit(onStepValid)}
            >
              Next
            </Button>
          )}

          {step === 5 && (
            <Button
              type="button"
              variant="primary"
              onClick={() => navigate('/app')}
            >
              Continue
            </Button>
          )}
        </div>
      </FormProvider>
    </div>
  );
};

export default MultiStepForm;

import React from 'react';
import { Controller, useFormContext } from 'react-hook-form';

import { MultiStepFormData } from '../multi-step-form.component';
import { Input } from '@shared/ui';

import './step-two.styles.scss';

const StepTwo: React.FC = () => {
  const { control } = useFormContext<MultiStepFormData>();

  return (
    <div className="step-two">
      <Controller
        name="title"
        control={control}
        rules={{
          maxLength: {
            value: 50,
            message: 'Titles must be 50 characters or fewer',
          },
          minLength: {
            value: 2,
            message: 'Title must be at least 2 characters',
          },
        }}
        render={({ field, fieldState }) => {
          const hasError = !!fieldState.error;
          return (
            <>
              <label className="onboarding-input-label">Title</label>
              <Input
                type="text"
                value={field.value}
                onChange={field.onChange}
                name={field.name}
                className={`form-input onboarding-form-input${
                  hasError ? ' onboarding-form-input__error' : ''
                }`}
                placeholder="E.g. Teacher, Creator, etc."
                aria-describedby={
                  fieldState.error ? `${field.name}-error` : undefined
                }
                onBlur={(e: { target: { value: string } }) =>
                  field.onChange(e.target.value.trim())
                }
                isMaxLengthShown={true}
                maxLength={50}
              />
              {fieldState.error && (
                <p className="form-field-error error-text-red">
                  {fieldState.error.message}
                </p>
              )}
            </>
          );
        }}
      />
    </div>
  );
};

export default StepTwo;

