import React, { useEffect, useState } from 'react';
import { Controller, useFormContext } from 'react-hook-form';
import { useSelector } from 'react-redux';

import { MultiStepFormData } from '../multi-step-form.component';
import { Input } from '@shared/ui';

import { selectAuthUser } from 'core/store/auth-store';
import { SocialMediaLink, SocialPlatforms } from 'core/api/models';
import {
  LocationSearchPlace,
  SocialMediaInput,
  OSMLocationSearch,
} from 'domains/app/components';

import './step-four.styles.scss';

interface StepFourProps {
  // eslint-disable-next-line no-unused-vars
  onSocialMediaChange: (links: SocialMediaLink[]) => void;
}

const StepFour: React.FC<StepFourProps> = ({ onSocialMediaChange }) => {
  const user = useSelector(selectAuthUser);
  const { control, setValue } = useFormContext<MultiStepFormData>();
  const [initialLinks, setInitialLinks] = useState<SocialMediaLink[]>([]);

  // URL regex:
  // ^(https?:\/\/)?      optional “http://” or “https://”
  // (www\.)?             optional “www.”
  // [\w-]+               domain label (letters, digits, underscore, hyphen)
  // (\.[\w-]+)+          one or more “.something” (e.g. .com, .co.uk)
  // ([/?#].*)?           optional path, query or anchor
  // $                    end of string
  const URL_PATTERN = /^(https?:\/\/)?(www\.)?[\w-]+(\.[\w-]+)+([/?#].*)?$/i;

  useEffect(() => {
    if (user && user.socialLinks) {
      setInitialLinks(user.socialLinks);
    } else {
      setInitialLinks([
        {
          id: 'id_1',
          platform: SocialPlatforms.IG,
          url: 'InstagramURL',
        },
        {
          id: 'id_2',
          platform: SocialPlatforms.TT,
          url: 'TiktokURL',
        },
      ]);
    }
  }, [user]);

  const handleSelect = (location: LocationSearchPlace) => {
    setValue('city', location.city, {
      shouldValidate: true,
      shouldDirty: true,
    });
    setValue('country', location.country, {
      shouldValidate: true,
      shouldDirty: true,
    });
    setValue('lat', String(location.lat), {
      shouldValidate: true,
      shouldDirty: true,
    });
    setValue('long', String(location.lon), {
      shouldValidate: true,
      shouldDirty: true,
    });
  };

  const handleSocialMediaChange = (socialLinks: SocialMediaLink[]) => {
    onSocialMediaChange(socialLinks);
  };

  return (
    <div className="step-four">
      <Controller
        name="website"
        control={control}
        rules={{
          pattern: {
            value: URL_PATTERN,
            message:
              'Enter a valid URL (e.g. https://example.com or www.example.com)',
          },
        }}
        render={({ field, fieldState }) => {
          const hasError = !!fieldState.error;
          return (
            <>
              <Input
                className={`form-input onboarding-form-input${
                  hasError ? ' onboarding-form-input__error' : ''
                }`}
                placeholder="Website"
                type="text"
                value={field.value}
                onChange={field.onChange}
                name={field.name}
              />
              {fieldState.error && (
                <p className="form-field-error error-text-red">
                  {fieldState.error.message}
                </p>
              )}
            </>
          );
        }}
      />

      <div className="user-location-search-container">
        <OSMLocationSearch onSelect={handleSelect} />
      </div>

      <div className="social-media-circle-container">
        <SocialMediaInput
          initialSocialLinks={initialLinks}
          onChange={handleSocialMediaChange}
        />
      </div>
    </div>
  );
};

export default StepFour;

import React from 'react';
import clsx from 'clsx';
import { IconType } from 'react-icons';

import { Icon } from '../icon';
import { getCssVar } from '@shared/utils';

import './input.styles.scss';

export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  value: string | number;
  required?: boolean;
  maxLength?: number;
  className?: string;
  error?: string;
  prefixIcon?: IconType;
  suffixIcon?: IconType;
  handleSuffixClick?: () => void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

const Input: React.FC<InputProps> = ({
  label,
  required,
  value,
  maxLength = 999,
  type = 'text',
  className,
  error,
  readOnly,
  disabled,
  prefixIcon,
  suffixIcon,
  handleSuffixClick,
  ...otherProps
}) => {
  const {
    ['aria-describedby']: ariaDescribedBy,
    ...inputProps
  } = otherProps;
  const errorId = error && inputProps.name ? `${inputProps.name}-error` : undefined;
  const describedBy = [ariaDescribedBy, errorId].filter(Boolean).join(' ') || undefined;
  const inputClass = clsx('input-field', {
    'input-error': error,
    'input-with-prefix': prefixIcon,
    readOnly,
    disabled,
  });

  return (
    <div className={clsx('input-wrapper', className)}>
      {label && (
        <label htmlFor={inputProps.name} className="input-label">
          {label}
        </label>
      )}
      <div className="input-row">
        {prefixIcon && (
          <Icon
            className="input-prefix"
            icon={prefixIcon}
            color={getCssVar('--text-secondary')}
            size={19}
          />
        )}
        <input
          className={inputClass}
          {...inputProps}
          required={required}
          id={inputProps.name}
          data-testid={`input-${inputProps.name}`}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          value={value}
          maxLength={maxLength}
          type={type}
        />
        {suffixIcon && (
          <button
            type="button"
            onClick={handleSuffixClick}
            className="input-suffix"
          >
            <Icon
              icon={suffixIcon}
              color={getCssVar('--text-secondary')}
              size={18}
            />
          </button>
        )}
      </div>
      {error && (
        <span id={errorId} className="input-error-message">
          {error}
        </span>
      )}
    </div>
  );
};

export default Input;

import React, { useLayoutEffect, useRef } from 'react';
import clsx from 'clsx';

import './textarea.styles.scss';

interface TextareaProps
  extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  label?: string;
  value: string;
  required?: boolean;
  isMaxLengthShown?: boolean;
  maxLength?: number;
  error?: string;
  block?: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

const Textarea: React.FC<TextareaProps> = ({
  label,
  value,
  isMaxLengthShown = false,
  maxLength = 999,
  className,
  block = false,
  error,
  ...otherProps
}) => {
  const {
    ['aria-describedby']: ariaDescribedBy,
    ...textareaProps
  } = otherProps;
  const errorId =
    error && textareaProps.name ? `${textareaProps.name}-error` : undefined;
  const describedBy = [ariaDescribedBy, errorId].filter(Boolean).join(' ') || undefined;
  const ref = useRef<HTMLTextAreaElement>(null);

  // After each render where `value` changed, adjust height
  useLayoutEffect(() => {
    const ta = ref.current;
    if (!ta) {
      return;
    }
    ta.style.height = 'auto'; // reset
    ta.style.height = ta.scrollHeight + 'px'; // expand
  }, [value]);

  return (
    <div className={clsx('textarea-wrapper', className)}>
      {label && (
        <label htmlFor={textareaProps.name} className="input-label">
          {label}
        </label>
      )}
      <div className="textarea-wrapper">
        <textarea
          className={clsx('textarea-field', { block, 'input-error': error })}
          ref={ref}
          value={value}
          {...textareaProps}
          id={textareaProps.name}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          maxLength={maxLength}
        />
        {isMaxLengthShown && (
          <span className="textarea-max-value">
            {String(value ?? '').length} / {maxLength}
          </span>
        )}
      </div>

      {error && (
        <span id={errorId} className="input-error-message">
          {error}
        </span>
      )}
    </div>
  );
};

export default Textarea;

import React, { ReactNode, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import clsx from 'clsx';
import { HiX } from 'react-icons/hi';

import { Button } from '../button';
import { Icon } from '../icon';
import { getCssVar } from '@shared/utils';

import './drawer.styles.scss';

interface DrawerProps {
  open: boolean;
  title: ReactNode;
  children: ReactNode;
  onClose: () => void;
  footer?: ReactNode;
  className?: string;
  closeLabel?: string;
}

const focusableSelector = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

const Drawer: React.FC<DrawerProps> = ({
  open,
  title,
  children,
  onClose,
  footer,
  className,
  closeLabel = 'Close drawer',
}) => {
  const panelRef = useRef<HTMLElement>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!open) {
      return undefined;
    }

    previousFocusRef.current = document.activeElement as HTMLElement | null;
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    window.setTimeout(() => {
      const firstFocusable = panelRef.current?.querySelector<HTMLElement>(
        focusableSelector,
      );
      firstFocusable?.focus();
    }, 0);

    return () => {
      document.body.style.overflow = originalOverflow;
      previousFocusRef.current?.focus?.();
    };
  }, [open]);

  useEffect(() => {
    if (!open) {
      return undefined;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
        return;
      }

      if (event.key !== 'Tab' || !panelRef.current) {
        return;
      }

      const focusable = Array.from(
        panelRef.current.querySelectorAll<HTMLElement>(focusableSelector),
      );

      if (focusable.length === 0) {
        event.preventDefault();
        panelRef.current.focus();
        return;
      }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onClose, open]);

  if (!open) {
    return null;
  }

  return createPortal(
    <div className="drawer-layer">
      <button
        type="button"
        className="drawer-overlay"
        aria-label={closeLabel}
        onClick={onClose}
      />
      <section
        ref={panelRef}
        className={clsx('drawer-panel', className)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="drawer-title"
        tabIndex={-1}
      >
        <header className="drawer-header">
          <div id="drawer-title" className="drawer-title">
            {title}
          </div>
          <Button
            type="button"
            variant="tertiary"
            size="icon"
            aria-label={closeLabel}
            onClick={onClose}
          >
            <Icon icon={HiX} size={20} color={getCssVar('--text-primary')} />
          </Button>
        </header>
        <div className="drawer-body">{children}</div>
        {footer && <footer className="drawer-footer">{footer}</footer>}
      </section>
    </div>,
    document.body,
  );
};

export default Drawer;

import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';

import {
  GoogleLoginRequest,
  LoginRequest,
  RegisterRequest,
  UpdateUserRequest,
  User,
  UserRole,
} from 'core/api/models';
import {
  registerUser,
  verifyEmailApi,
  signInUser,
  googleAPI,
  getUserProfileAPI,
  logoutAPI,
  updateUserDetailsAPI,
  changeDevUserRoleAPI,
} from 'core/api/services';
import { extractErrorMessage } from '@shared/utils';

interface AuthState {
  user: null | User;
  loading: boolean;
  error: string | null;
  isUserLoggedIn: boolean | null;
}

const initialState: AuthState = {
  user: null,
  loading: false,
  error: null,
  isUserLoggedIn: null,
};

// Registration thunk: returns a success message from the backend.
export const signupUser = createAsyncThunk<
  { response: string }, // Return type: success message
  RegisterRequest, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/signupUser', async (userData, { rejectWithValue }) => {
  try {
    const response = await registerUser(userData);
    return { response }; // API returns a success message
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

// Verify email thunk: calls the verify endpoint with the token.
export const verifyEmail = createAsyncThunk<
  string,
  string,
  { rejectValue: string } // Error type
>('auth/verifyEmail', async (token: string, { rejectWithValue }) => {
  try {
    const response = await verifyEmailApi(token);
    return response.data; // API returns a success message
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

// Sign in thunk: returns the user info along with a token.
export const signinUser = createAsyncThunk<
  string, // Return type: user login response
  LoginRequest, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/signinUser', async (userData, { dispatch, rejectWithValue }) => {
  try {
    const response = await signInUser(userData);
    if (response === 'Login successful') {
      dispatch(getUserProfile());
    }
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const googleSignInUser = createAsyncThunk<
  string, // Return type: google login response
  GoogleLoginRequest, // Argument type (token)
  { rejectValue: string } // Error type
>('auth/googleSignInUser', async (idToken, { dispatch, rejectWithValue }) => {
  try {
    const response = await googleAPI(idToken);
    if (!response) {
      // If response is null or falsy, reject with an error message.
      return rejectWithValue('Signin failed');
    }
    dispatch(getUserProfile());
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const getUserProfile = createAsyncThunk<
  User, // Return type: user login response
  void, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/getUserProfile', async (_, { rejectWithValue }) => {
  try {
    const response = await getUserProfileAPI();
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const logoutUser = createAsyncThunk<
  void, // Return type
  void, // Argument type
  { rejectValue: string } // Error type
>('auth/logoutUser', async (_, { rejectWithValue }) => {
  try {
    // Assuming httpClient is your axios instance configured to include credentials.
    await logoutAPI();
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const updateUserDetails = createAsyncThunk<
  User, // Return type: user login response
  UpdateUserRequest, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/updateUserDetails', async (userData, { rejectWithValue }) => {
  try {
    const response = await updateUserDetailsAPI(userData);
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const changeDevUserRole = createAsyncThunk<
  User,
  UserRole,
  { rejectValue: string }
>('auth/changeDevUserRole', async (role, { rejectWithValue }) => {
  try {
    return await changeDevUserRoleAPI(role);
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    // This action can be used to rehydrate the token on app load
    // setToken: (state, action: PayloadAction<string>) => {
    //   state.token = action.payload;
    // },
    setUserProfile: (state, action: PayloadAction<User>) => {
      state.user = action.payload;
    },
    logout: (state) => {
      state.user = null;
      state.isUserLoggedIn = null;
    },
    resetOnboarding: (state) => {
      // Reset any onboarding state if needed
      // This can be expanded based on your onboarding logic
      if (state.user) {
        state.user.onboardingCompleted = false;
      }

      state.isUserLoggedIn = true;
    },
  },
  extraReducers: (builder) => {
    builder
      // Registration cases:
      .addCase(signupUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(signupUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(signupUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Signup failed';
      })
      // Verification cases:
      .addCase(verifyEmail.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(verifyEmail.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(verifyEmail.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Verification failed';
      })
      // Sign in cases:
      .addCase(signinUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(signinUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(signinUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Signin failed';
      })
      // Google Sign In
      .addCase(googleSignInUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(googleSignInUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(googleSignInUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Google Signin failed';
      })
      // Get User Profile
      .addCase(getUserProfile.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(
        getUserProfile.fulfilled,
        (state, action: PayloadAction<User>) => {
          state.loading = false;
          state.user = action.payload;
          state.isUserLoggedIn = true;
        },
      )
      .addCase(getUserProfile.rejected, (state) => {
        state.loading = false;
        state.isUserLoggedIn = false;
        state.error = 'Get User Profile failed';
      })
      .addCase(logoutUser.fulfilled, (state) => {
        state.user = null;
        state.isUserLoggedIn = null;
      })
      .addCase(logoutUser.rejected, (state, action) => {
        // Optionally handle logout errors here.
        state.error = action.payload || 'Logout failed';
      })

      .addCase(updateUserDetails.pending, (state) => {
        state.loading = true;
      })
      .addCase(
        updateUserDetails.fulfilled,
        (state, action: PayloadAction<User>) => {
          state.loading = false;
          state.user = action.payload;
        },
      )
      .addCase(updateUserDetails.rejected, (state) => {
        state.loading = false;
        state.error = 'Update user details failed';
      })
      .addCase(changeDevUserRole.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(
        changeDevUserRole.fulfilled,
        (state, action: PayloadAction<User>) => {
          state.loading = false;
          state.user = action.payload;
          state.isUserLoggedIn = true;
        },
      )
      .addCase(changeDevUserRole.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Change dev user role failed';
      });
  },
});

export const { logout, setUserProfile, resetOnboarding } = authSlice.actions;
export default authSlice.reducer;

/* eslint-disable no-console */
import httpClient from '../../http-client';
import { UpdateUserRequest } from '../../models/user/update-user-request';
import { User, UserRole } from '../../models/user/user';

export const getUserProfileAPI = async () => {
  try {
    const response = await httpClient.get<User>('api/user/userInfo', {
      headers: { 'X-CSRF-Force': true },
    });
    return response.data;
  } catch (error) {
    console.error('Error getting user profile:', error);
    throw error;
  }
};

export const updateUserDetailsAPI = async (payload: UpdateUserRequest) => {
  try {
    const response = await httpClient.put<User>('api/user/userInfo', payload, {
      withCredentials: true,
    });
    return response.data;
  } catch (error) {
    console.error('Error updating user details:', error);
    throw error;
  }
};

export const changeDevUserRoleAPI = async (role: UserRole) => {
  try {
    const response = await httpClient.put<User>(
      'api/user/dev/role',
      { role },
      { withCredentials: true },
    );
    return response.data;
  } catch (error) {
    console.error('Error changing dev user role:', error);
    throw error;
  }
};

package com.myproject.video.video_platform.dto.user;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Size;
import jakarta.validation.constraints.Email;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

@Data
@NoArgsConstructor
@AllArgsConstructor
@Schema(description = "Profile fields that the authenticated user may update.")
public class UpdateUserRequest {
    @Schema(description = "Deprecated compatibility field. The authenticated user is always updated.", deprecated = true)
    private String userId;

    @Size(max = 100)
    private String firstName;

    @Size(max = 100)
    private String lastName;

    @Email
    @Size(max = 320)
    private String publicEmail;

    @Size(max = 100)
    @Schema(description = "Public title shown on storefront", example = "Lifestyle Photographer")
    private String title;

    @Size(max = 1000)
    @Schema(description = "Short biography", example = "Helping creatives build their first paid lifestyle shoots.")
    private String bio;

    @Size(max = 500)
    @Schema(description = "Mission tagline", example = "Teach lifestyle photographers how to lead confident shoots")
    private String taglineMission;

    @Size(max = 255)
    @Schema(description = "Personal website", example = "https://ameliahughes.studio")
    private String website;

    @Size(max = 100)
    @Schema(description = "City", example = "Berlin")
    private String city;

    @Size(max = 100)
    @Schema(description = "Country", example = "Germany")
    private String country;

    /**
     * Full replacement set:
     * • null = leave links unchanged
     * • empty = remove all links
     * • items w/ null id = new links
     * • items w/ existing id = update that link
     * • any existing link not referenced by id here = delete
     */
    @Valid
    @Schema(description = "Full replacement list of social links")
    private List<SocialMediaLinkUpdateRequest> socialLinks;
}

