import React from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Toaster } from 'sonner';

import RoutesDev from './devtools/__routes-dev';
import { DevDashboard, NotFoundPage, UnauthorizedPage } from '@shared/pages';
import { AppInitializer } from 'core/providers';
import { AppRouter } from '@domains/app/routes';
import { AuthRouter } from '@domains/auth/routes';
import { MarketingRouter } from '@domains/marketing/routes';

interface LegacyAuthRedirectProps {
  to: string;
}

const LegacyAuthRedirect: React.FC<LegacyAuthRedirectProps> = ({ to }) => {
  const location = useLocation();
  return <Navigate to={`${to}${location.search}${location.hash}`} replace />;
};

const App = () => (
  <AppInitializer>
    <Toaster position="top-center" richColors closeButton />

    <Routes>
      {/* App domain */}
      <Route path="/app/*" element={<AppRouter />} />
      {/* Onboarding (root) is defined inside AppRouter as absolute /onboarding */}
      <Route path="/onboarding" element={<AppRouter />} />

      {/* Auth domain */}
      <Route path="/auth/*" element={<AuthRouter />} />
      {/* Legacy auth aliases */}
      <Route path="/signin" element={<LegacyAuthRedirect to="/auth/login" />} />
      <Route path="/signup" element={<LegacyAuthRedirect to="/auth/signup" />} />
      <Route path="/login" element={<LegacyAuthRedirect to="/auth/login" />} />
      <Route
        path="/verify-email"
        element={<LegacyAuthRedirect to="/auth/verify-email" />}
      />
      <Route
        path="/email-sent"
        element={<LegacyAuthRedirect to="/auth/email-sent" />}
      />
      <Route
        path="/forgot-password"
        element={<LegacyAuthRedirect to="/auth/forgot-password" />}
      />

      {/* Shared/system routes */}
      <Route path="/unauthorized" element={<UnauthorizedPage />} />
      <Route path="/dev-dashboard" element={<DevDashboard />} />

      {process.env.NODE_ENV === 'development' && (
        <Route path="/__routes-dev" element={<RoutesDev />} />
      )}

      {/* Marketing domain */}
      <Route path="/*" element={<MarketingRouter />} />

      {/* Fallback */}
      <Route path="*" element={<NotFoundPage />} />
    </Routes>
  </AppInitializer>
);

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { Provider } from 'react-redux';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

import App from './App';
import { store } from './core/store/store';
// import reportWebVitals from './reportWebVitals';

import './styles/index.scss';

const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement,
);
const queryClient = new QueryClient();
root.render(
  <React.StrictMode>
    <Provider store={store}>
      <QueryClientProvider client={queryClient}>
        <BrowserRouter>
          <App />
        </BrowserRouter>
      </QueryClientProvider>
    </Provider>
  </React.StrictMode>,
);

// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
// reportWebVitals(console.log);

import { configureStore, createListenerMiddleware } from '@reduxjs/toolkit';
import authReducer from './auth-store/auth.slice';
import adminReducer from './admin-store/admin.slice';
import analyticsReducer from './analytics-store/analytics.slice';
import productsReducer from './product-store/product.slice';
import customersReducer from './customers-store/customers.slice';
import dashboardReducer from './dashboard-store/dashboard.slice';
import membershipReducer from './membership-store/membership.slice';
import notificationsReducer from './notifications/notifications.slice';
import productLandingPageReducer from './product-landing-page-store/product-landing-page.slice';
import salesReducer from './sales-store/sales.slice';
import storefrontReducer from './storefront-store/storefront.slice';
import shopCartReducer, {
  loadCartFromStorage,
  saveCartToStorage,
  ShopCartState,
} from './shop-cart/shop-cart.slice';
import wishlistReducer from './wishlist/wishlist.slice';
import { setupProductListeners } from './listeners/product-listeners';
import { reviewsSlice } from './reviews-store';

const listenerMiddleware = createListenerMiddleware();

setupProductListeners(listenerMiddleware);

const preloadedCart = loadCartFromStorage();

export const store = configureStore({
  reducer: {
    auth: authReducer,
    admin: adminReducer,
    analytics: analyticsReducer,
    products: productsReducer,
    customers: customersReducer,
    dashboard: dashboardReducer,
    membership: membershipReducer,
    notifications: notificationsReducer,
    productLandingPage: productLandingPageReducer,
    sales: salesReducer,
    storefront: storefrontReducer,
    shopCart: shopCartReducer,
    wishlist: wishlistReducer,
    reviews: reviewsSlice,
  },
  preloadedState: preloadedCart
    ? ({ shopCart: preloadedCart } as { shopCart: ShopCartState })
    : undefined,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().prepend(listenerMiddleware.middleware),
});

let lastSaved: string | null = null;
store.subscribe(() => {
  const state = store.getState().shopCart as ShopCartState;
  const snapshot = JSON.stringify(state);
  if (snapshot !== lastSaved) {
    saveCartToStorage(state);
    lastSaved = snapshot;
  }
});

