export const deleteDownloadSectionFile = createAsyncThunk<
  { productId: string; sectionId: string; fileId: string },
  { productId: string; sectionId: string; fileId: string },
  { rejectValue: string }
>('products/deleteDownloadSectionFile', async (payload, thunkAPI) => {
  try {
    const fileId = await deleteSectionFileAPI(
