import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { FaRegHeart } from 'react-icons/fa';
import { FaHeart } from 'react-icons/fa';

import { ProductMinimised, AppDispatch } from 'core/api/models';
import { getAllProductsMinimalAPI } from 'core/api/services';
import { Icon, Button } from '@shared/ui';
import { appRoutes } from '../../routes/routes';
import {
  selectAllShopCartProducts,
  addProductToCart,
} from 'core/store/shop-cart';
import { selectWishlistIds, toggleWishlist } from 'core/store/wishlist';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../assets/image-placeholder.png');

import './explore-page.styles.scss';

const ExplorePage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch<AppDispatch>();
  const cartProducts = useSelector(selectAllShopCartProducts);
  const wishlistIds = useSelector(selectWishlistIds);
  const [products, setProducts] = useState<ProductMinimised[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true; // ↪️ prevent state updates after unmount

    // call your service
    getAllProductsMinimalAPI()
      .then((data) => {
        if (isMounted) {
          setProducts(data);
        }
      })
      .catch((err) => {
        console.error(err);
        if (isMounted) {
          setError('Failed to load products.');
        }
      })
      .finally(() => {
        if (isMounted) {
          setLoading(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, []); // empty deps → runs once on mount

  const handleAddToCart = (prod: ProductMinimised) => {
    dispatch(addProductToCart(prod));
  };

  const handleToggleWishlist = (prod: ProductMinimised) => {
    dispatch(toggleWishlist(prod));
  };

  const isInCart = (productId: string | undefined) =>
    cartProducts?.some((p) => p.id === productId);

  if (loading) {
    return <p>Loading products…</p>;
  }
  if (error) {
    return <p>{error}</p>;
  }
  return (
    <div className="explore-page">
      <main className="explore-page-content">
        <section className="intro">
          <h1>Check this out</h1>
          <p>
            Here we show products. This is where people search for products or
            instructors
          </p>
          <p>
            All types of users have access to this page, even visitors (people
            without an account)
          </p>
          <p>
            All types of registered users (User, Creator, Admin) have a quick
            access link to this page
          </p>
        </section>
        <section className="explore-products">
          <h1>These are our best products</h1>
          <div className="products-list">
            {products?.map((product, idx) => {
              const wished = wishlistIds.has(product.id);
              const productName = product.title ?? 'Untitled product';

              return (
                <div key={idx} className="product-card">
                  <img
                    src={placeholderImage}
                    alt={productName}
                    className="product-card-image"
                  />

                  <button
                    type="button"
                    className={`wish-btn ${wished ? 'is-active' : ''}`}
                    aria-pressed={wished}
                    aria-label={
                      wished ? 'Remove from wishlist' : 'Add to wishlist'
                    }
                    onClick={() => handleToggleWishlist(product)}
                    title={wished ? 'Remove from wishlist' : 'Add to wishlist'}
                  >
                    {wished ? (
                      <Icon icon={FaHeart} size={22} color="red" />
                    ) : (
                      <Icon icon={FaRegHeart} size={22} />
                    )}
                  </button>
                  <div className="product-card-details">
                    <div className="last-updated-line">
                      <span>
                        {product.updatedAt &&
                          new Date(product.updatedAt).toLocaleDateString(
                            'en-GB',
                            {
                              day: 'numeric',
                              month: 'long',
                              year: 'numeric',
                            },
                          )}
                      </span>
                    </div>
                    <h3>{productName}</h3>
                    <div className="type-and-price-line">
                      <span>{product.type?.toLowerCase()}</span>
                      <span>
                        {product.price !== 'free' && <span>&euro;</span>}
                        {product.price}
                      </span>
                    </div>
                    <button
                      type="button"
                      className="creator-route-btn"
                      onClick={() => navigate(`/store/${product.createdById}`)}
                    >
                      <span className="creator">
                        {product.createdByName}, {product.createdByTitle}
                      </span>
                    </button>
                  </div>
                  <div className="explore-card-actions">
                    <Button
                      type="button"
                      variant="secondary"
                      onClick={() =>
                        navigate(appRoutes.product(product.id, product.type))
                      }
                    >
                      View Product
                    </Button>
                    <Button
                      type="button"
                      variant="primary"
                      disabled={isInCart(product.id)}
                      onClick={() => {
                        if (!isInCart(product.id)) {
                          handleAddToCart(product);
                        }
                      }}
                    >
                      {isInCart(product.id) ? 'Already in cart' : 'Add to cart'}
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      </main>
    </div>
  );
};

export default ExplorePage;

import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { FaSearch } from 'react-icons/fa';
import { BiSort } from 'react-icons/bi';
import { MdOutlineTypeSpecimen } from 'react-icons/md';
import { SiStatuspal } from 'react-icons/si';

import { selectAuthUser } from 'core/store/auth-store';
import {
  getProductSummariesByOwner,
  selectProductSummaries,
  selectProductsLoading,
  selectProductsError,
} from 'core/store/product-store';
import { PRODUCT_FILTER_OPTIONS } from 'core/constants';
import { Button, Input, Select, SelectOption } from '@shared/ui';
import { AppDispatch } from 'core/api/models';

import ProductManagementRow from './product-management-row.component';
import {
  defaultProductsFilterForm,
  filterAndSortProducts,
  ProductsFilterForm,
} from './products-list.utils';

import './products-list.styles.scss';

const ProductsList: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();

  const products = useSelector(selectProductSummaries);
  const loading = useSelector(selectProductsLoading);
  const error = useSelector(selectProductsError);
  const user = useSelector(selectAuthUser);
  const userId = user?.id;

  useEffect(() => {
    if (userId) {
      dispatch(getProductSummariesByOwner(userId));
    }
  }, [dispatch, userId]);

  const [filterForm, setFilterForm] = useState<ProductsFilterForm>(
    defaultProductsFilterForm,
  );

  const hasProducts = Boolean(products && products.length > 0);
  const filteredProducts = useMemo(
    () => filterAndSortProducts(products, filterForm),
    [products, filterForm],
  );

  const hasSearch = filterForm.search.trim().length > 0;
  const hasFilters =
    filterForm.statusFilter !== 'all' || filterForm.typeFilter !== 'all';
  const hasActiveRefinement = hasSearch || hasFilters;
  const resultCountLabel = `${filteredProducts.length} ${
    filteredProducts.length === 1 ? 'product' : 'products'
  }`;

  const handleControlChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value } = event.target;
    setFilterForm((current) => ({ ...current, [name]: value }));
  };

  const clearSearch = () =>
    setFilterForm((current) => ({ ...current, search: '' }));

  const clearFilters = () => setFilterForm(defaultProductsFilterForm);

  const TYPE_OPTIONS: SelectOption[] = [
    { label: 'All types', value: 'all' },
    ...PRODUCT_FILTER_OPTIONS.map((option) => ({
      label: option.label,
      value: option.type,
    })),
  ];

  const STATUS_OPTIONS: SelectOption[] = [
    { label: 'All statuses', value: 'all' },
    { label: 'Published', value: 'PUBLISHED' },
    { label: 'Draft', value: 'DRAFT' },
  ];

  const SORT_OPTIONS: SelectOption[] = [
    { label: 'Recently updated', value: 'updated-desc' },
    { label: 'Newest', value: 'created-desc' },
    { label: 'Oldest', value: 'created-asc' },
    { label: 'Name A-Z', value: 'name-asc' },
    { label: 'Name Z-A', value: 'name-desc' },
  ];

  const renderState = (): React.ReactNode => {
    if (loading) {
      return (
        <div className="products-state products-state--loading" aria-live="polite">
          <div className="products-skeleton-row" />
          <div className="products-skeleton-row" />
          <div className="products-skeleton-row" />
        </div>
      );
    }

    if (error) {
      return (
        <div className="products-state" role="alert">
          <h2>Products could not load</h2>
          <p>{error}</p>
          {userId && (
            <Button
              type="button"
              variant="secondary"
              onClick={() => dispatch(getProductSummariesByOwner(userId))}
            >
              Retry
            </Button>
          )}
        </div>
      );
    }

    if (!hasProducts) {
      return (
        <div className="products-state">
          <h2>Create your first product</h2>
          <p>Start with a course, download, consultation, or membership.</p>
          <Button
            type="button"
            variant="primary"
            onClick={() => navigate('create')}
          >
            + Add product
          </Button>
        </div>
      );
    }

    if (filteredProducts.length === 0 && hasSearch) {
      return (
        <div className="products-state">
          <h2>{`No products match "${filterForm.search.trim()}".`}</h2>
          <p>Try another search.</p>
          <Button type="button" variant="secondary" onClick={clearSearch}>
            Clear search
          </Button>
        </div>
      );
    }

    if (filteredProducts.length === 0 && hasFilters) {
      return (
        <div className="products-state">
          <h2>No products match these filters.</h2>
          <p>Try a different type or status.</p>
          <Button type="button" variant="secondary" onClick={clearFilters}>
            Clear filters
          </Button>
        </div>
      );
    }

    return null;
  };

  return (
    <div className="products-page">
      <div className="products-header">
        <div>
          <h1>Products</h1>
          <p>Create and manage everything you sell.</p>
        </div>
        <Button
          className="add-product-btn"
          variant="primary"
          onClick={() => navigate('create')}
        >
          + Add product
        </Button>
      </div>

      {hasProducts && (
        <section className="products-toolbar" aria-label="Product controls">
          <Input
            value={filterForm.search}
            prefixIcon={FaSearch}
            onChange={handleControlChange}
            placeholder="Search products..."
            name="search"
            aria-label="Search products"
            className="products-toolbar__search"
          />
          <div className="products-toolbar__filters">
            <Select
              name="typeFilter"
              value={filterForm.typeFilter}
              options={TYPE_OPTIONS}
              onChange={handleControlChange}
              customClassName="products-toolbar__select"
              prefixIcon={MdOutlineTypeSpecimen}
              aria-label="Filter by product type"
            />
            <Select
              name="statusFilter"
              value={filterForm.statusFilter}
              options={STATUS_OPTIONS}
              onChange={handleControlChange}
              customClassName="products-toolbar__select"
              prefixIcon={SiStatuspal}
              aria-label="Filter by product status"
            />
            <Select
              name="sort"
              value={filterForm.sort}
              options={SORT_OPTIONS}
              onChange={handleControlChange}
              customClassName="products-toolbar__select products-toolbar__sort"
              prefixIcon={BiSort}
              aria-label="Sort products"
            />
          </div>
        </section>
      )}

      {hasProducts && (
        <div className="products-collection-meta">
          <span>{resultCountLabel}</span>
          {hasActiveRefinement && (
            <Button type="button" variant="tertiary" size="sm" onClick={clearFilters}>
              Clear filters
            </Button>
          )}
        </div>
      )}

      {renderState() || (
        <section className="products-management-list" aria-label="Products">
          <div className="products-management-list__header" aria-hidden="true">
            <span>Product</span>
            <span>Status</span>
            <span>Price</span>
            <span>Updated</span>
            <span>Actions</span>
          </div>
          <div className="products-management-list__rows">
            {filteredProducts.map((product) => (
              <ProductManagementRow
                product={product}
                key={product.id}
                showInspectionRecurringMembership={
                  process.env.REACT_APP_USE_MOCKS === 'true'
                }
              />
            ))}
          </div>
        </section>
      )}
    </div>
  );
};

export default ProductsList;

import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';
import { HiArrowLeft } from 'react-icons/hi';

import {
  AbstractProduct,
  AppDispatch,
  ProductStatus,
} from 'core/api/models';
import {
  clearCurrentProduct,
  getProductById,
  selectCurrentProduct,
  selectProductsError,
  selectProductsLoading,
} from 'core/store/product-store';
import { PRODUCT_TYPE_REGISTRY } from 'core/constants';
import { Button, Icon, StatusBadge, StatusBadgeTone } from '@shared/ui';
import { getCssVar } from '@shared/utils';
import { appRoutes } from 'domains/app/routes/routes';

import {
  formatProductDate,
  formatProductPrice,
  getProductStatusLabel,
  getProductTypeLabel,
} from '../products-list/products-list.utils';

import './product-overview.styles.scss';

// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../../assets/image-placeholder.png');

const productStatusTone: Record<ProductStatus, StatusBadgeTone> = {
  PUBLISHED: 'success',
  DRAFT: 'neutral',
  HIDDEN: 'warning',
};

const meetingMethodLabel: Record<string, string> = {
  ZOOM: 'Zoom',
  GOOGLE_MEET: 'Google Meet',
  PHONE: 'Phone',
  OTHER: 'Other',
};

const getProductTitle = (product: AbstractProduct) =>
  product.name?.trim() || 'Untitled product';

const getLastUpdatedLabel = (product: AbstractProduct) => {
  const updated = formatProductDate(product.updatedAt ?? product.createdAt, 'Not updated');

  return updated.iso ? (
    <time dateTime={updated.iso} title={updated.fullLabel}>
      Updated {updated.shortLabel}
    </time>
  ) : (
    updated.shortLabel
  );
};

const countLessons = (product: AbstractProduct) => {
  if (product.type !== 'COURSE') {
    return 0;
  }

  return product.sections?.reduce(
    (total, section) => total + (section.lessons?.length ?? 0),
    0,
  ) ?? 0;
};

const countFiles = (product: AbstractProduct) => {
  if (product.type !== 'DOWNLOAD') {
    return 0;
  }

  return product.sections?.reduce(
    (total, section) => total + (section.files?.length ?? 0),
    0,
  ) ?? 0;
};

const DefinitionList: React.FC<{
  rows: Array<{ label: string; value?: React.ReactNode }>;
}> = ({ rows }) => {
  const visibleRows = rows.filter(
    (row) => row.value !== undefined && row.value !== null && row.value !== '',
  );

  if (visibleRows.length === 0) {
    return null;
  }

  return (
    <dl className="product-overview-definition-list">
      {visibleRows.map((row) => (
        <div key={row.label}>
          <dt>{row.label}</dt>
          <dd>{row.value}</dd>
        </div>
      ))}
    </dl>
  );
};

const SectionOutline: React.FC<{ product: Extract<AbstractProduct, { type: 'COURSE' | 'DOWNLOAD' }> }> = ({
  product,
}) => {
  const sections = product.sections ?? [];
  const isCourse = product.type === 'COURSE';

  if (sections.length === 0) {
    return (
      <p className="product-overview-empty-copy">
        {isCourse
          ? 'No course sections have been added yet.'
          : 'No download sections have been added yet.'}
      </p>
    );
  }

  return (
    <div className="product-overview-outline">
      {sections.map((section, index) => {
        const itemCount = isCourse
          ? section.lessons?.length ?? 0
          : section.files?.length ?? 0;
        const itemLabel = isCourse
          ? `${itemCount} ${itemCount === 1 ? 'lesson' : 'lessons'}`
          : `${itemCount} ${itemCount === 1 ? 'file' : 'files'}`;

        return (
          <article key={section.id ?? `${section.title}-${index}`}>
            <div>
              <h3>{section.title || `Section ${index + 1}`}</h3>
              {section.description && <p>{section.description}</p>}
            </div>
            <span>{itemLabel}</span>
          </article>
        );
      })}
    </div>
  );
};

const ProductContentSummary: React.FC<{
  product: AbstractProduct;
  onEditProduct: () => void;
}> = ({
  product,
  onEditProduct,
}) => {
  if (product.type === 'COURSE') {
    const sectionCount = product.sections?.length ?? 0;
    const lessonCount = countLessons(product);

    return (
      <section className="product-overview-panel product-overview-panel--wide">
        <div className="product-overview-section-heading">
          <div>
            <h2>Course content</h2>
            <p>Read-only outline from the current product sections.</p>
          </div>
          <Button
            type="button"
            variant="secondary"
            onClick={onEditProduct}
          >
            Edit curriculum
          </Button>
        </div>
        <div className="product-overview-summary-strip" aria-label="Course summary">
          <article>
            <span>Sections</span>
            <strong>{sectionCount}</strong>
          </article>
          <article>
            <span>Lessons</span>
            <strong>{lessonCount}</strong>
          </article>
        </div>
        <SectionOutline product={product} />
      </section>
    );
  }

  if (product.type === 'DOWNLOAD') {
    const sectionCount = product.sections?.length ?? 0;
    const fileCount = countFiles(product);

    return (
      <section className="product-overview-panel product-overview-panel--wide">
        <div className="product-overview-section-heading">
          <div>
            <h2>Download contents</h2>
            <p>Read-only package summary from the loaded download sections.</p>
          </div>
          <Button
            type="button"
            variant="secondary"
            onClick={onEditProduct}
          >
            Edit files
          </Button>
        </div>
        <div className="product-overview-summary-strip" aria-label="Download summary">
          <article>
            <span>Sections</span>
            <strong>{sectionCount}</strong>
          </article>
          <article>
            <span>Files</span>
            <strong>{fileCount}</strong>
          </article>
        </div>
        <SectionOutline product={product} />
      </section>
    );
  }

  if (product.type === 'CONSULTATION') {
    const details = product.consultationDetails;

    return (
      <section className="product-overview-panel product-overview-panel--wide">
        <div className="product-overview-section-heading">
          <div>
            <h2>Consultation setup</h2>
            <p>Configured appointment details for this product.</p>
          </div>
          <Button
            type="button"
            variant="secondary"
            onClick={onEditProduct}
          >
            Edit availability
          </Button>
        </div>
        {details ? (
          <DefinitionList
            rows={[
              {
                label: 'Duration',
                value: details.durationMinutes
                  ? `${details.durationMinutes} minutes`
                  : undefined,
              },
              {
                label: 'Meeting method',
                value: details.meetingMethod
                  ? meetingMethodLabel[details.meetingMethod] ?? details.meetingMethod
                  : undefined,
              },
              { label: 'Location', value: details.customLocation },
              {
                label: 'Buffer before',
                value:
                  details.bufferBeforeMinutes !== undefined
                    ? `${details.bufferBeforeMinutes} minutes`
                    : undefined,
              },
              {
                label: 'Buffer after',
                value:
                  details.bufferAfterMinutes !== undefined
                    ? `${details.bufferAfterMinutes} minutes`
                    : undefined,
              },
              {
                label: 'Max sessions per day',
                value: details.maxSessionsPerDay,
              },
              {
                label: 'Connected calendars',
                value:
                  details.connectedCalendars && details.connectedCalendars.length > 0
                    ? `${details.connectedCalendars.length} connected`
                    : undefined,
              },
              { label: 'Confirmation message', value: details.confirmationMessage },
              { label: 'Cancellation policy', value: details.cancellationPolicy },
            ]}
          />
        ) : (
          <p className="product-overview-empty-copy">
            Consultation details have not been configured yet.
          </p>
        )}
      </section>
    );
  }

  return (
    <section className="product-overview-panel product-overview-panel--wide">
      <div className="product-overview-section-heading">
        <div>
          <h2>Membership setup</h2>
          <p>
            Membership Overview V1 shows only Product-owned information and
            configured recurring pricing.
          </p>
        </div>
        <Button
          type="button"
          variant="secondary"
          onClick={onEditProduct}
        >
          Edit membership
        </Button>
      </div>
      <p className="product-overview-empty-copy">
        Member counts, subscriber access, revenue, and Membership content summaries
        need dedicated backend-backed contracts before they appear here.
      </p>
    </section>
  );
};

const ProductOverview: React.FC = () => {
  const { productId } = useParams();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const product = useSelector(selectCurrentProduct);
  const loading = useSelector(selectProductsLoading);
  const error = useSelector(selectProductsError);

  useEffect(() => {
    dispatch(clearCurrentProduct());

    if (productId) {
      dispatch(getProductById({ productId }));
    }
  }, [dispatch, productId]);

  const loadedProduct = product?.id === productId ? product : null;
  const productTitle = loadedProduct ? getProductTitle(loadedProduct) : '';
  const productTypeLabel = loadedProduct
    ? getProductTypeLabel(loadedProduct.type)
    : 'Product';
  const productIcon = loadedProduct
    ? PRODUCT_TYPE_REGISTRY[loadedProduct.type].displayIcon
    : undefined;
  const productStatus = loadedProduct?.status ?? 'DRAFT';
  const created = useMemo(
    () => formatProductDate(loadedProduct?.createdAt, 'Not created'),
    [loadedProduct?.createdAt],
  );
  const updated = useMemo(
    () => formatProductDate(loadedProduct?.updatedAt, 'Not updated'),
    [loadedProduct?.updatedAt],
  );

  if (!productId) {
    return (
      <div className="product-overview-page">
        <Button
          type="button"
          variant="tertiary"
          className="product-overview-back"
          onClick={() => navigate(appRoutes.products)}
        >
          <Icon icon={HiArrowLeft} size={18} color={getCssVar('--brand-primary')} />
          <span>Products</span>
        </Button>
        <div className="product-overview-state">
          <h2>Product not found</h2>
          <p>This product route is missing a product ID.</p>
        </div>
      </div>
    );
  }

  if (loading && !loadedProduct) {
    return (
      <div className="product-overview-page">
        <Button
          type="button"
          variant="tertiary"
          className="product-overview-back"
          onClick={() => navigate(appRoutes.products)}
        >
          <Icon icon={HiArrowLeft} size={18} color={getCssVar('--brand-primary')} />
          <span>Products</span>
        </Button>
        <div className="product-overview-state product-overview-state--loading" role="status">
          <div className="product-overview-skeleton product-overview-skeleton--hero" />
          <div className="product-overview-skeleton" />
          <div className="product-overview-skeleton" />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="product-overview-page">
        <Button
          type="button"
          variant="tertiary"
          className="product-overview-back"
          onClick={() => navigate(appRoutes.products)}
        >
          <Icon icon={HiArrowLeft} size={18} color={getCssVar('--brand-primary')} />
          <span>Products</span>
        </Button>
        <div className="product-overview-state" role="alert">
          <h2>Product data is not available yet</h2>
          <p>{error}</p>
          <Button
            type="button"
            variant="secondary"
            onClick={() => dispatch(getProductById({ productId }))}
          >
            Retry
          </Button>
        </div>
      </div>
    );
  }

  if (!loadedProduct) {
    return (
      <div className="product-overview-page">
        <Button
          type="button"
          variant="tertiary"
          className="product-overview-back"
          onClick={() => navigate(appRoutes.products)}
        >
          <Icon icon={HiArrowLeft} size={18} color={getCssVar('--brand-primary')} />
          <span>Products</span>
        </Button>
        <div className="product-overview-state">
          <h2>Product not found</h2>
          <p>This product is not available.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="product-overview-page">
      <Button
        type="button"
        variant="tertiary"
        className="product-overview-back"
        onClick={() => navigate(appRoutes.products)}
      >
        <Icon icon={HiArrowLeft} size={18} color={getCssVar('--brand-primary')} />
        <span>Products</span>
      </Button>

      <header className="product-overview-hero">
        <img
          className="product-overview-hero__thumbnail"
          src={loadedProduct.imageUrl || placeholderImage}
          alt=""
          aria-hidden="true"
        />
        <div className="product-overview-hero__identity">
          <div className="product-overview-hero__eyebrow">
            <span aria-hidden="true">{productIcon}</span>
            <span>{productTypeLabel}</span>
            <StatusBadge
              label={getProductStatusLabel(productStatus)}
              tone={productStatusTone[productStatus] ?? 'neutral'}
              size="sm"
            />
          </div>
          <h1>{productTitle}</h1>
          {loadedProduct.description ? (
            <p>{loadedProduct.description}</p>
          ) : (
            <p className="product-overview-muted">No description has been added yet.</p>
          )}
          <div className="product-overview-hero__updated">
            {getLastUpdatedLabel(loadedProduct)}
          </div>
        </div>
        <div className="product-overview-hero__actions">
          <Button
            type="button"
            variant="primary"
            onClick={() => navigate(appRoutes.productsEdit(loadedProduct.id))}
          >
            Edit product
          </Button>
          <Button
            type="button"
            variant="secondary"
            onClick={() =>
              navigate(appRoutes.productsLandingPage(loadedProduct.id))
            }
          >
            Edit landing page
          </Button>
          {loadedProduct.status === 'PUBLISHED' && (
            <Button
              type="button"
              variant="secondary"
              onClick={() =>
                navigate(appRoutes.product(loadedProduct.id, loadedProduct.type))
              }
            >
              View public page
            </Button>
          )}
        </div>
      </header>

      <div className="product-overview-grid">
        <section className="product-overview-panel">
          <h2>Product details</h2>
          <DefinitionList
            rows={[
              { label: 'Status', value: getProductStatusLabel(productStatus) },
              { label: 'Product type', value: productTypeLabel },
              { label: 'Price', value: formatProductPrice(loadedProduct) },
              {
                label: 'Created',
                value: created.iso ? (
                  <time dateTime={created.iso} title={created.fullLabel}>
                    {created.shortLabel}
                  </time>
                ) : (
                  created.shortLabel
                ),
              },
              {
                label: 'Updated',
                value: updated.iso ? (
                  <time dateTime={updated.iso} title={updated.fullLabel}>
                    {updated.shortLabel}
                  </time>
                ) : (
                  updated.shortLabel
                ),
              },
            ]}
          />
        </section>

        <ProductContentSummary
          product={loadedProduct}
          onEditProduct={() => navigate(appRoutes.productsEdit(loadedProduct.id))}
        />
      </div>
    </div>
  );
};

export default ProductOverview;

