/* eslint-disable no-console */
import axios, { AxiosInstance } from 'axios';
import { attachCsrfInterceptor } from './interceptors/csrf';
import { attachRefreshTokenInterceptor } from './interceptors/refresh-token';

const API_BASE_URL = process.env.REACT_APP_BASE_PATH;

const httpClient: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  },
  withCredentials: true,
});

// Wire up the CSRF interceptor first:
attachCsrfInterceptor(httpClient);

// Then wire up the refresh‐token interceptor:
attachRefreshTokenInterceptor(httpClient);

// --------------------------------------------------------------------
// Only load mocks if the “USE_MOCKS” env var is set to “true”
// (you can also check `window.location.hostname === 'localhost'` if preferred)

console.info('[USE_MOCKS]', process.env.REACT_APP_USE_MOCKS);

if (process.env.REACT_APP_USE_MOCKS === 'true') {
  // We use require() here so that when this file is bundled for production,
  // it won’t accidentally pull in the mock module.
  // Local mocks are maintained source and should remain registered through the
  // shared API client so components keep using the production service path.
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupMocks } = require('./_mocks');
    setupMocks(httpClient);
    console.info('[Mocks] axios-mocks enabled');
  } catch (e) {
    console.warn('[Mocks] could not load ./_mocks (file not found)');
  }
}

export default httpClient;

import { AxiosInstance, InternalAxiosRequestConfig } from 'axios';
import { getCookie } from '@shared/utils';

/**
 * Attaches a request interceptor that automatically adds
 * X-XSRF-TOKEN from cookies on any state‐changing request.
 */
export function attachCsrfInterceptor(httpClient: AxiosInstance) {
  const excluded = [
    '/api/auth/register',
    '/api/auth/login',
    '/api/auth/verify',
  ];

  httpClient.interceptors.request.use(
    (config: InternalAxiosRequestConfig) => {
      // Skip attaching CSRF for excluded endpoints
      if (
        config.url &&
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        excluded.some((endpoint) => config.url!.includes(endpoint))
      ) {
        return config;
      }

      // Only attach token on POST/PUT/DELETE/PATCH or if header 'X-CSRF-Force' is set
      const methodsRequiringCsrf = ['post', 'put', 'delete', 'patch'];
      if (
        (config.method &&
          methodsRequiringCsrf.includes(config.method.toLowerCase())) ||
        config.headers?.['X-CSRF-Force']
      ) {
        const csrfToken = getCookie('XSRF-TOKEN');
        if (csrfToken) {
          config.headers = config.headers || {};
          config.headers['X-XSRF-TOKEN'] = csrfToken;
        }
      }
      return config;
    },
    (error) => Promise.reject(error),
  );
}

/* eslint-disable @typescript-eslint/no-non-null-assertion */
/* eslint-disable no-unused-vars */
import { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';

let isRefreshing = false;
let failedQueue: Array<{
  resolve: (token: string) => void;
  reject: (error: unknown) => void;
}> = [];

const processQueue = (error: unknown, token: string | null = null) => {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else if (token) {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

/**
 * Attaches a response interceptor to handle 401s by
 * requesting a token refresh and replaying failed requests.
 */
export function attachRefreshTokenInterceptor(httpClient: AxiosInstance) {
  httpClient.interceptors.response.use(
    (response: AxiosResponse) => response,
    (error) => {
      const originalRequest = error.config as AxiosRequestConfig & {
        _retry?: boolean;
      };

      // If status is 401, and we haven't already retried this request:
      if (error.response?.status === 401 && !originalRequest._retry) {
        // If the request was the refresh endpoint itself, just reject:
        if (
          originalRequest.url &&
          originalRequest.url.includes('api/auth/refresh')
        ) {
          return Promise.reject(error);
        }

        if (isRefreshing) {
          // Queue up the request until the refresh finishes
          return new Promise((resolve, reject) => {
            failedQueue.push({ resolve, reject });
          })
            .then((token) => {
              // Once refreshed, retry the original
              originalRequest.headers!['Authorization'] = `Bearer ${token}`;
              return httpClient.request(originalRequest);
            })
            .catch((err) => Promise.reject(err));
        }

        originalRequest._retry = true;
        isRefreshing = true;

        return new Promise((resolve, reject) => {
          httpClient
            .post(
              'api/auth/refresh',
              {},
              { withCredentials: true }
            )
            .then((res) => {
              // Backend should have updated the cookie(s). If you need
              // a fresh Authorization: Bearer header, extract it from res here.
              const newToken = res.data.token; // or however your backend returns it
              processQueue(null, newToken);

              // Retry original request
              originalRequest.headers!['Authorization'] = `Bearer ${newToken}`;
              resolve(httpClient.request(originalRequest));
            })
            .catch((err) => {
              processQueue(err, null);
              reject(err);
            })
            .finally(() => {
              isRefreshing = false;
            });
        });
      }

      return Promise.reject(error);
    }
  );
}

