import { configureStore, createListenerMiddleware } from '@reduxjs/toolkit';
import authReducer from './auth-store/auth.slice';
import adminReducer from './admin-store/admin.slice';
import analyticsReducer from './analytics-store/analytics.slice';
import productsReducer from './product-store/product.slice';
import customersReducer from './customers-store/customers.slice';
import dashboardReducer from './dashboard-store/dashboard.slice';
import membershipReducer from './membership-store/membership.slice';
import notificationsReducer from './notifications/notifications.slice';
import productLandingPageReducer from './product-landing-page-store/product-landing-page.slice';
import salesReducer from './sales-store/sales.slice';
import storefrontReducer from './storefront-store/storefront.slice';
import shopCartReducer, {
  loadCartFromStorage,
  saveCartToStorage,
  ShopCartState,
} from './shop-cart/shop-cart.slice';
import wishlistReducer from './wishlist/wishlist.slice';
import { setupProductListeners } from './listeners/product-listeners';
import { reviewsSlice } from './reviews-store';

const listenerMiddleware = createListenerMiddleware();

setupProductListeners(listenerMiddleware);

const preloadedCart = loadCartFromStorage();

export const store = configureStore({
  reducer: {
    auth: authReducer,
    admin: adminReducer,
    analytics: analyticsReducer,
    products: productsReducer,
    customers: customersReducer,
    dashboard: dashboardReducer,
    membership: membershipReducer,
    notifications: notificationsReducer,
    productLandingPage: productLandingPageReducer,
    sales: salesReducer,
    storefront: storefrontReducer,
    shopCart: shopCartReducer,
    wishlist: wishlistReducer,
    reviews: reviewsSlice,
  },
  preloadedState: preloadedCart
    ? ({ shopCart: preloadedCart } as { shopCart: ShopCartState })
    : undefined,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().prepend(listenerMiddleware.middleware),
});

let lastSaved: string | null = null;
store.subscribe(() => {
  const state = store.getState().shopCart as ShopCartState;
  const snapshot = JSON.stringify(state);
  if (snapshot !== lastSaved) {
    saveCartToStorage(state);
    lastSaved = snapshot;
  }
});

import { createListenerMiddleware } from '@reduxjs/toolkit';
import {
  createProduct,
  addImageToProduct,
  updateProductDetails,
  createProductSection,
  updateProductSection,
  createCourseLesson,
  updateCourseLesson,
} from '../product-store/product.slice';
import { addNotification } from '../notifications/notifications.slice';

export const setupProductListeners = (
  listenerMiddleware: ReturnType<typeof createListenerMiddleware>
) => {
  listenerMiddleware.startListening({
    actionCreator: createProduct.fulfilled,
    effect: async (action, listenerApi) => {
      const { name } = action.payload;
      listenerApi.dispatch(
        addNotification({
          message: `Your product ${name} has been created successfully!`,
          type: 'SUCCESS',
          title: 'Product Created',
        })
      );
    },
  });

  listenerMiddleware.startListening({
    actionCreator: addImageToProduct.fulfilled,
    effect: async (action, listenerApi) => {
      listenerApi.dispatch(
        addNotification({
          message: 'Product image updated successfully!',
          type: 'SUCCESS',
          title: 'Image Upload',
        })
      );
    },
  });

  listenerMiddleware.startListening({
    actionCreator: updateProductDetails.fulfilled,
    effect: async (action, listenerApi) => {
      const { name } = action.payload;
      listenerApi.dispatch(
        addNotification({
          message: `Product ${name} updated successfully!`,
          type: 'SUCCESS',
          title: 'Product Updated',
        })
      );
    },
  });

  listenerMiddleware.startListening({
    actionCreator: createProductSection.fulfilled,
    effect: async (action, listenerApi) => {
      const { title } = action.payload;
      listenerApi.dispatch(
        addNotification({
          message: `Section ${title} created successfully!`,
          type: 'SUCCESS',
          title: 'Section Created',
        })
      );
    },
  });

  listenerMiddleware.startListening({
    actionCreator: updateProductSection.fulfilled,
    effect: async (action, listenerApi) => {
      listenerApi.dispatch(
        addNotification({
          message: `Section ${action.payload.title} updated successfully!`,
          type: 'SUCCESS',
          title: 'Section Updated',
        })
      );
    },
  });

  listenerMiddleware.startListening({
    actionCreator: createCourseLesson.fulfilled,
    effect: async (action, listenerApi) => {
      const { title } = action.payload;
      listenerApi.dispatch(
        addNotification({
          message: `Lesson ${title} created successfully!`,
          type: 'SUCCESS',
          title: 'Lesson Created',
        })
      );
    },
  });

  listenerMiddleware.startListening({
    actionCreator: updateCourseLesson.fulfilled,
    effect: async (action, listenerApi) => {
      listenerApi.dispatch(
        addNotification({
          message: `Lesson ${action.payload.title} updated successfully!`,
          type: 'SUCCESS',
          title: 'Lesson Updated',
        })
      );
    },
  });
};

import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

import { INotification } from 'core/api/models';

interface NotificationsState {
  notifications: INotification[];
}

const initialState: NotificationsState = {
  notifications: [],
};

const notificationsSlice = createSlice({
  name: 'notifications',
  initialState,
  reducers: {
    addNotification: (
      state,
      action: PayloadAction<Omit<INotification, 'id' | 'isRead'>>,
    ) => {
      state.notifications.push({
        ...action.payload,
        id: uuidv4(),
        isRead: false,
      });
    },
    removeNotification: (state, action: PayloadAction<string>) => {
      state.notifications = state.notifications.filter(
        (n) => n.id !== action.payload,
      );
    },
    markAsRead: (state, action: PayloadAction<string>) => {
      const notification = state.notifications.find(
        (n) => n.id === action.payload,
      );
      if (notification) {
        notification.isRead = true;
      }
    },
  },
});

export const { addNotification, removeNotification, markAsRead } =
  notificationsSlice.actions;
export default notificationsSlice.reducer;

