import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';
import DOMPurify from 'dompurify';
import { toast } from 'sonner';

import {
  AppDispatch,
  hasRole,
  ProductMinimised,
  RootState,
  UserRole,
} from 'core/api/models';
import {
  enrollInFreeProductAPI,
  getProductAccessAPI,
  getProductFileDownloadAPI,
} from 'core/api/services';
import { selectAuthUser } from 'core/store/auth-store';
import {
  clearCurrentProduct,
  getProductById,
  selectCurrentProduct,
  selectProductsError,
  selectProductsLoading,
} from 'core/store/product-store';
import {
  fetchPublicProductLandingPageConfig,
  selectPublicProductLandingPageConfigByProductId,
} from 'core/store/product-landing-page-store';
import {
  fetchPublicStorefront,
  selectCreatorStorefrontConfig,
  selectPublicStorefrontByCreatorId,
} from 'core/store/storefront-store';
import { addProductToCart, selectCartIds } from 'core/store/shop-cart';
import { Button, LegacyExpansionPanel } from '@shared/ui';
import {
  getProductLandingPageViewModel,
  isPublicProductLandingPageProduct,
  ProductLandingPage,
} from 'domains/app/features/product-landing-page';
import { appRoutes } from '../../routes/routes';

import './product-page.styles.scss';

const ProductPage: React.FC = () => {
  const { type, id } = useParams();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartIds = useSelector(selectCartIds);
  const currentProduct = useSelector(selectCurrentProduct);
  const loading = useSelector(selectProductsLoading);
  const error = useSelector(selectProductsError);
  const creatorStorefrontConfig = useSelector(selectCreatorStorefrontConfig);
  const [hasAccess, setHasAccess] = useState(false);
  const [enrolling, setEnrolling] = useState(false);
  const loadedProduct =
    currentProduct?.id && currentProduct.id === id ? currentProduct : null;
  const publicStorefront = useSelector((state: RootState) =>
    selectPublicStorefrontByCreatorId(state, loadedProduct?.userId),
  );
  const landingPageConfig = useSelector((state: RootState) =>
    selectPublicProductLandingPageConfigByProductId(state, loadedProduct?.id),
  );
  const isOwner =
    Boolean(user?.id && user.id === loadedProduct?.userId) ||
    hasRole(user?.roles, UserRole.ADMIN);

  useEffect(() => {
    if (id) {
      dispatch(clearCurrentProduct());
      dispatch(getProductById({ productId: id }));
    }
  }, [dispatch, id]);

  useEffect(() => {
    if (loadedProduct && type && loadedProduct.type !== type) {
      navigate(appRoutes.product(loadedProduct.id), { replace: true });
    }
  }, [loadedProduct, navigate, type]);

  useEffect(() => {
    if (!user || !id) {
      setHasAccess(false);
      return;
    }

    getProductAccessAPI(id)
      .then((access) => setHasAccess(access.hasAccess))
      .catch(() => setHasAccess(false));
  }, [id, user]);

  useEffect(() => {
    if (
      loadedProduct?.userId &&
      isPublicProductLandingPageProduct(loadedProduct) &&
      !publicStorefront
    ) {
      dispatch(fetchPublicStorefront(loadedProduct.userId));
    }
  }, [dispatch, loadedProduct, publicStorefront]);

  useEffect(() => {
    if (loadedProduct && isPublicProductLandingPageProduct(loadedProduct)) {
      dispatch(fetchPublicProductLandingPageConfig(loadedProduct.id));
    }
  }, [dispatch, loadedProduct]);

  const viewModel = useMemo(() => {
    if (!loadedProduct || !isPublicProductLandingPageProduct(loadedProduct)) {
      return null;
    }

    return getProductLandingPageViewModel({
      product: loadedProduct,
      currentUser: user,
      publicStorefront,
      creatorStorefrontTheme: isOwner
        ? creatorStorefrontConfig?.theme
        : undefined,
      landingPageConfig,
    });
  }, [
    creatorStorefrontConfig?.theme,
    isOwner,
    landingPageConfig,
    loadedProduct,
    publicStorefront,
    user,
  ]);

  const numericPrice =
    loadedProduct?.price === 'free' ? 0 : Number(loadedProduct?.price ?? 0);
  const isFree = numericPrice === 0;
  const isMembershipProduct = loadedProduct?.type === 'MEMBERSHIP';
  const isInCart = Boolean(loadedProduct?.id && cartIds.has(loadedProduct.id));

  const toSummary = (): ProductMinimised | null => {
    if (!loadedProduct) {
      return null;
    }
    return {
      id: loadedProduct.id,
      title: loadedProduct.name,
      description: loadedProduct.description,
      type: loadedProduct.type,
      price: loadedProduct.price,
      status: loadedProduct.status,
      imageUrl: loadedProduct.imageUrl,
      createdById: loadedProduct.userId,
      createdAt: loadedProduct.createdAt,
      updatedAt: loadedProduct.updatedAt,
    };
  };

  const handleEnroll = async () => {
    if (!user) {
      navigate('/auth/login');
      return;
    }
    if (!loadedProduct) {
      return;
    }

    setEnrolling(true);
    try {
      await enrollInFreeProductAPI(loadedProduct.id);
      setHasAccess(true);
      await dispatch(getProductById({ productId: loadedProduct.id })).unwrap();
      toast.success('Added to your library');
    } catch {
      toast.error('This product could not be added to your library.');
    } finally {
      setEnrolling(false);
    }
  };

  const handleAddToCart = () => {
    const product = toSummary();
    if (product && !isInCart) {
      dispatch(addProductToCart(product));
    }
  };

  const handleDownload = async (fileId?: string) => {
    if (!loadedProduct || !fileId) {
      return;
    }
    try {
      const { url } = await getProductFileDownloadAPI(
        loadedProduct.id,
        fileId,
      );
      window.location.assign(url);
    } catch {
      toast.error('The download could not be started.');
    }
  };

  if (loading && !loadedProduct) {
    return (
      <main className="product-page-state" aria-busy="true">
        <h1>Loading Product</h1>
        <p>Preparing this Product page.</p>
      </main>
    );
  }

  if (error || !loadedProduct) {
    return (
      <main className="product-page-state" role="alert">
        <h1>Product unavailable</h1>
        <p>{error ?? 'This Product page could not be loaded.'}</p>
      </main>
    );
  }

  if (!viewModel) {
    return (
      <main className="product-page-state" role="alert">
        <h1>Product unavailable</h1>
        <p>This Product is not publicly available.</p>
      </main>
    );
  }

  const commerceActions = isOwner ? (
    <Button
      type="button"
      variant="primary"
      onClick={() => navigate(appRoutes.productsEdit(loadedProduct.id))}
    >
      Edit product
    </Button>
  ) : hasAccess ? (
    <Button type="button" variant="primary" disabled>
      In your library
    </Button>
  ) : isFree ? (
    <Button
      type="button"
      variant="primary"
      disabled={enrolling}
      onClick={handleEnroll}
    >
      {enrolling ? 'Adding...' : 'Enroll for free'}
    </Button>
  ) : isMembershipProduct ? (
    <Button type="button" variant="primary" disabled>
      Membership checkout unavailable
    </Button>
  ) : (
    <div className="product-page__commerce-actions">
      <Button
        type="button"
        variant="primary"
        disabled={isInCart}
        onClick={handleAddToCart}
      >
        {isInCart ? 'Already in cart' : 'Add to cart'}
      </Button>
      <Button
        type="button"
        variant="secondary"
        onClick={() => {
          handleAddToCart();
          navigate(appRoutes.cart);
        }}
      >
        Buy now
      </Button>
    </div>
  );

  return (
    <>
      <ProductLandingPage product={viewModel} commerceActions={commerceActions} />
      {(hasAccess || isOwner) && loadedProduct.type === 'COURSE' && (
        <section className="product-page__protected-content">
          <h2>Course content</h2>
          {loadedProduct.sections?.map((section) => (
            <LegacyExpansionPanel key={section.id} header={section.title || ''}>
              {section.description && <p>{section.description}</p>}
              {section.lessons?.map((lesson) => (
                <article key={lesson.id} className="product-page__lesson">
                  <h3>{lesson.title}</h3>
                  {lesson.content && (
                    <div
                      dangerouslySetInnerHTML={{
                        __html: DOMPurify.sanitize(lesson.content),
                      }}
                    />
                  )}
                  {lesson.videoUrl && (
                    <video controls src={lesson.videoUrl}>
                      <track kind="captions" />
                    </video>
                  )}
                </article>
              ))}
            </LegacyExpansionPanel>
          ))}
        </section>
      )}
      {(hasAccess || isOwner) && loadedProduct.type === 'DOWNLOAD' && (
        <section className="product-page__protected-content">
          <h2>Downloads</h2>
          {loadedProduct.sections?.map((section) => (
            <LegacyExpansionPanel key={section.id} header={section.title || ''}>
              {section.files?.map((file) => (
                <button
                  key={file.id}
                  type="button"
                  className="product-page__download"
                  onClick={() => handleDownload(file.id)}
                >
                  {file.fileName}
                </button>
              ))}
            </LegacyExpansionPanel>
          ))}
        </section>
      )}
    </>
  );
};

export default ProductPage;

import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

import { ProductMinimised, AppDispatch } from 'core/api/models';
import { Button } from '@shared/ui';
import { selectAuthUser } from 'core/store/auth-store';
import {
  selectAllShopCartProducts,
  selectShopCartTotal,
  removeProductFromCart,
  moveCartItemToWishlist,
  clearShoppingCart,
} from 'core/store/shop-cart';
import { selectWishlistIds } from 'core/store/wishlist';
import { enrollInFreeProductAPI } from 'core/api/services';
import {
  formatCommerceAmount,
  getCartCheckoutKind,
  getCommerceErrorMessage,
  isSuccessfulOrderStatus,
  isTerminalUnsuccessfulOrderStatus,
  startPaidCheckout,
  validatePaidCart,
} from './cart-checkout.utils';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../assets/image-placeholder.png');

import './cart.styles.scss';

const Cart: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartProducts = useSelector(selectAllShopCartProducts);
  const cartTotal = useSelector(selectShopCartTotal);
  const wishlistIds = useSelector(selectWishlistIds);
  const [checkingOut, setCheckingOut] = useState(false);
  const cartCheckoutKind = getCartCheckoutKind(cartProducts);
  const containsPaidProducts = cartCheckoutKind === 'PAID';
  const containsMixedProducts = cartCheckoutKind === 'MIXED';

  const handleRemoveFromCart = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(removeProductFromCart(prod.id));
    }
  };

  const handleMoveToWishlist = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(moveCartItemToWishlist(prod.id));
    }
  };

  const handleFreeCheckout = async () => {
    const productIds = cartProducts
      .map((product) => product.id)
      .filter((id): id is string => Boolean(id));
    if (productIds.length === 0 || containsPaidProducts) {
      return;
    }

    setCheckingOut(true);
    try {
      await Promise.all(productIds.map(enrollInFreeProductAPI));
      dispatch(clearShoppingCart());
      toast.success('Products added to your library');
      navigate('/app/library/all-products');
    } catch {
      toast.error('The free products could not be added to your library.');
    } finally {
      setCheckingOut(false);
    }
  };

  const handlePaidCheckout = async () => {
    const validation = validatePaidCart(cartProducts, user?.id);
    if (!validation.valid) {
      toast.error(validation.message);
      return;
    }

    setCheckingOut(true);
    try {
      const { session, order } = await startPaidCheckout(cartProducts);

      if (session.checkoutUrl) {
        return;
      }

      if (!order) {
        toast.info('Checkout started. Your cart has been saved.');
        return;
      }

      const amount = formatCommerceAmount(order.totalMinor, order.currency);

      if (isSuccessfulOrderStatus(order.status)) {
        dispatch(clearShoppingCart());
        toast.success(
          amount
            ? `Payment confirmed for ${amount}. Products added to your library.`
            : 'Payment confirmed. Products added to your library.',
        );
        navigate('/app/library/all-products');
        return;
      }

      if (order.status === 'PENDING') {
        toast.info('Payment is still pending. Your cart has been saved.');
        return;
      }

      if (isTerminalUnsuccessfulOrderStatus(order.status)) {
        toast.error('Payment was not completed. Your cart has been saved.');
      }
    } catch (error) {
      toast.error(getCommerceErrorMessage(error));
    } finally {
      setCheckingOut(false);
    }
  };

  const handleCheckout = () => {
    if (containsMixedProducts) {
      toast.error(
        'Free and paid products cannot be checked out together. Please split your cart.',
      );
      return;
    }

    if (containsPaidProducts) {
      void handlePaidCheckout();
      return;
    }

    void handleFreeCheckout();
  };

  return (
    <div className="cart-page">
      <h1 className="cart-page-title">Shopping Cart</h1>
      {cartProducts.length > 0 ? (
        <>
          <section className="cart-container">
            <div className="cart-container-line">
              <p>{cartProducts.length} products in your cart</p>
              <hr className="cart-underline"></hr>
            </div>
            <article className="cart-products-container">
              <div className="cart-products-list">
                {cartProducts.map((prod) => {
                  const isInWishlist = wishlistIds.has(prod.id);
                  const productTitle = prod.title ?? 'Untitled product';

                  return (
                    <div key={prod.id} className="cart-product">
                      <img
                        src={placeholderImage}
                        alt={productTitle}
                        className="product-card-image"
                      />
                      <div className="cart-product-details">
                        <h3>{productTitle}</h3>
                        <p>By {prod.createdByName}</p>
                        <p>4.7 ⭐⭐⭐⭐⭐ (32,025 ratings)</p>
                      </div>
                      <div className="cart-product-actions">
                        <button
                          type="button"
                          onClick={() => handleRemoveFromCart(prod)}
                        >
                          Remove
                        </button>
                        <button
                          type="button"
                          disabled={isInWishlist}
                          onClick={() => handleMoveToWishlist(prod)}
                        >
                          Move to wishlist
                        </button>
                      </div>
                      <div className="cart-product-price-tag">
                        €{prod.price}
                      </div>
                    </div>
                  );
                })}
              </div>
            </article>
            <aside className="cart-products-aside">
              <h4>Total:</h4>
              <h2>
                {cartTotal && cartTotal > 0 ? (
                  <span>€{cartTotal}</span>
                ) : (
                  <span>free</span>
                )}
              </h2>
              {containsPaidProducts && (
                <p className="cart-products-aside__notice" role="note">
                  Test payment — No real charge will be made during checkout.
                </p>
              )}

              <Button
                type="button"
                variant="primary"
                disabled={checkingOut}
                onClick={handleCheckout}
              >
                {checkingOut ? 'Processing...' : 'Proceed to checkout'}
              </Button>
              {containsMixedProducts && (
                <p role="alert" className="cart-products-aside__message">
                  Free and paid products cannot be checked out together. Please
                  split your cart.
                </p>
              )}
            </aside>
          </section>
        </>
      ) : (
        <p>You don&apos;t have any products in your shopping cart</p>
      )}
      <div className="cart-page-bottom">
        <h2>You might also like</h2>
      </div>
    </div>
  );
};

export default Cart;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import {
  ProductEntitlement,
  ProductType,
} from 'core/api/models';
import { getMyEntitlementsAPI } from 'core/api/services';
import { Button } from '@shared/ui';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../assets/image-placeholder.png');

import './library-page.styles.scss';

interface LibraryProductsProps {
  type?: ProductType;
}

const LibraryProducts: React.FC<LibraryProductsProps> = ({ type }) => {
  const navigate = useNavigate();
  const [entitlements, setEntitlements] = useState<ProductEntitlement[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError(null);

    getMyEntitlementsAPI({ type })
      .then((result) => {
        if (mounted) {
          setEntitlements(result);
        }
      })
      .catch(() => {
        if (mounted) {
          setError('Your library could not be loaded.');
        }
      })
      .finally(() => {
        if (mounted) {
          setLoading(false);
        }
      });

    return () => {
      mounted = false;
    };
  }, [type]);

  if (loading) {
    return <p>Loading your library...</p>;
  }

  if (error) {
    return <p role="alert">{error}</p>;
  }

  if (entitlements.length === 0) {
    return <p>You do not have any products in this section yet.</p>;
  }

  return (
    <div className="library-products">
      {entitlements.map(({ id, product }) => (
        <article key={id} className="library-product">
          <img
            src={product.imageUrl || placeholderImage}
            alt={product.title || 'Product'}
          />
          <div>
            <h2>{product.title || 'Untitled product'}</h2>
            <p>{product.type}</p>
            <p>{product.description}</p>
          </div>
          <Button
            type="button"
            variant="primary"
            onClick={() => navigate(`/app/product/${product.id}`)}
          >
            Open
          </Button>
        </article>
      ))}
    </div>
  );
};

