@Service
public class CommerceCheckoutService {

    private final CommerceOrderRepository orderRepository;
    private final CommercePaymentAttemptRepository paymentAttemptRepository;
    private final ProductRepository productRepository;
    private final ProductEntitlementRepository entitlementRepository;
    private final UserRepository userRepository;
    private final CurrentUserService currentUserService;
    private final CommerceOrderMapper orderMapper;
    private final PaymentGateway paymentGateway;
    private final boolean commerceEnabled;
    private final String currency;
    private final Duration sessionExpiry;
    private final CommercePaymentEventService paymentEventService;
    private final boolean fakeAutoSuccess;

    public CommerceCheckoutService(
            CommerceOrderRepository orderRepository,
            CommercePaymentAttemptRepository paymentAttemptRepository,
            ProductRepository productRepository,
            ProductEntitlementRepository entitlementRepository,
            UserRepository userRepository,
            CurrentUserService currentUserService,
            CommerceOrderMapper orderMapper,
            CommercePaymentEventService paymentEventService,
            ObjectProvider<PaymentGateway> paymentGatewayProvider,
            @Value("${app.commerce.enabled:false}") boolean commerceEnabled,
            @Value("${app.commerce.currency:EUR}") String currency,
            @Value("${app.commerce.session-expiry-minutes:30}") long sessionExpiryMinutes,
            @Value("${app.commerce.fake.auto-success:false}") boolean fakeAutoSuccess
    ) {
        this.orderRepository = orderRepository;
        this.paymentAttemptRepository = paymentAttemptRepository;
        this.productRepository = productRepository;
        this.entitlementRepository = entitlementRepository;
        this.userRepository = userRepository;
        this.currentUserService = currentUserService;
        this.orderMapper = orderMapper;
        this.paymentEventService = paymentEventService;
        this.paymentGateway = paymentGatewayProvider.getIfAvailable();
        this.commerceEnabled = commerceEnabled;
        String normalizedCurrency = currency == null
                ? ""
                : currency.trim().toUpperCase(Locale.ROOT);
        if (!"EUR".equals(normalizedCurrency)) {
            throw new IllegalArgumentException("Commerce currently supports EUR only");
        }
        if (sessionExpiryMinutes <= 0) {
            throw new IllegalArgumentException("Commerce session expiry must be positive");
        }
        this.currency = normalizedCurrency;
        this.sessionExpiry = Duration.ofMinutes(sessionExpiryMinutes);
        this.fakeAutoSuccess = fakeAutoSuccess;
    }

    @Transactional
    public CommerceOrderResponse createCheckout(
            CommerceCheckoutRequest request,
            String idempotencyKey
    ) {
        requireCommerceAvailable();
        String normalizedKey = normalizeIdempotencyKey(idempotencyKey);
        UUID buyerId = currentUserService.getCurrentUserId();
        List<UUID> productIds = request.getProductIds();
        requireUniqueProductIds(productIds);
        String fingerprint = fingerprint(productIds);

        // Serialize checkout creation per buyer so concurrent retries cannot create
        // duplicate orders before the idempotency-key uniqueness constraint is visible.
        User buyer = userRepository.findByIdForCommerceCheckout(buyerId)
                .orElseThrow(() -> new UserNotFoundException("User not found: " + buyerId));

        CommerceOrder existing = orderRepository
                .findByBuyerUserIdAndIdempotencyKey(buyerId, normalizedKey)
                .orElse(null);
        if (existing != null) {
            if (!existing.getCheckoutFingerprint().equals(fingerprint)) {
                throw new CommerceException(
                        HttpStatus.CONFLICT,
                        "The idempotency key was already used for a different checkout"
                );
            }
            expireIfNecessary(existing);
            return orderMapper.toResponse(existing);
        }

        List<Product> products = productRepository.findAllById(productIds);
        if (products.size() != productIds.size()) {
            throw invalidCheckout("One or more Products do not exist");
        }

        User creator = validateProducts(products, buyerId);
        Instant expiresAt = Instant.now().plus(sessionExpiry);
        CommerceOrder order = new CommerceOrder();
        order.setBuyer(buyer);
        order.setCreator(creator);
        order.setStatus(CommerceOrderStatus.PENDING);
        order.setCurrency(currency);
        order.setIdempotencyKey(normalizedKey);
        order.setCheckoutFingerprint(fingerprint);
        order.setExpiresAt(expiresAt);

        long total = 0L;
        for (Product product : products) {
            long amountMinor = toMinorUnits(product.getPrice());
            total = addAmounts(total, amountMinor);
            CommerceOrderItem item = new CommerceOrderItem();
            item.setProductId(product.getId());
            item.setProductType(product.getType());
            item.setProductName(product.getName());
            item.setUnitAmountMinor(amountMinor);
            item.setQuantity(1);
            item.setLineTotalMinor(amountMinor);
            order.addItem(item);
        }
        order.setSubtotalMinor(total);
        order.setTotalMinor(total);
        order = orderRepository.saveAndFlush(order);

        CheckoutGatewaySession session = paymentGateway.createCheckoutSession(
                new CheckoutGatewayCommand(
                        order.getId(),
                        buyer.getEmail(),
                        total,
                        currency,
                        expiresAt
                )
        );
        validateGatewaySession(session);
        CommercePaymentAttempt attempt = new CommercePaymentAttempt();
        attempt.setOrder(order);
        attempt.setProvider(paymentGateway.provider());
        attempt.setStatus(PaymentAttemptStatus.PENDING);
        attempt.setProviderSessionId(session.providerSessionId());
        attempt.setCheckoutUrl(session.checkoutUrl());
        attempt.setAmountMinor(total);
        attempt.setCurrency(currency);
        paymentAttemptRepository.saveAndFlush(attempt);

        if (fakeAutoSuccess && paymentGateway.provider() == PaymentProvider.FAKE) {
            paymentEventService.process(new NormalizedPaymentEvent(
                    PaymentProvider.FAKE,
                    "fake-paid-" + order.getId(),
                    order.getId(),
                    PaymentEventType.PAID,
                    "fake-payment-" + order.getId(),
                    total,
                    currency
            ));
        }

        return orderMapper.toResponse(order);
    }

    private User validateProducts(List<Product> products, UUID buyerId) {
        User creator = null;
        for (Product product : products) {
            if (product.getType() == ProductType.MEMBERSHIP
                    || product.getPricingModel() == ProductPricingModel.RECURRING) {
                throw invalidCheckout("Recurring and Membership Products cannot use one-time checkout");
            }
            if (product.getStatus() != ProductStatus.PUBLISHED) {
                throw invalidCheckout("Only published Products can be purchased");
            }
            if (product.getPrice() == null || product.getPrice().compareTo(BigDecimal.ZERO) <= 0) {
                throw invalidCheckout("Free Products must use the enrollment flow");
            }
            if (product.getUser().getUserId().equals(buyerId)) {
                throw invalidCheckout("Creators cannot purchase their own Products");
            }
            if (creator == null) {
                creator = product.getUser();
            } else if (!creator.getUserId().equals(product.getUser().getUserId())) {
                throw invalidCheckout("A checkout can contain Products from only one Creator");
            }
            if (entitlementRepository.existsByUserUserIdAndProductIdAndStatus(
                    buyerId,
                    product.getId(),
                    EntitlementStatus.ACTIVE
            )) {
                throw new CommerceException(
                        HttpStatus.CONFLICT,
                        "The buyer already has access to one or more Products"
                );
            }
            toMinorUnits(product.getPrice());
        }
        return creator;
    }

    private void requireCommerceAvailable() {
        if (!commerceEnabled || paymentGateway == null) {
            throw new CommerceException(
                    HttpStatus.SERVICE_UNAVAILABLE,
                    "Paid checkout is not configured"
            );
        }
    }

    private static String normalizeIdempotencyKey(String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank() || idempotencyKey.length() > 128) {
            throw new CommerceException(
                    HttpStatus.BAD_REQUEST,
                    "A valid Idempotency-Key header is required"
            );
        }
        return idempotencyKey.trim();
    }

    private static void requireUniqueProductIds(List<UUID> productIds) {
        Set<UUID> uniqueIds = new HashSet<>(productIds);
        if (uniqueIds.size() != productIds.size()) {
            throw invalidCheckout("Duplicate Products are not allowed in one checkout");
        }
    }

    private static long toMinorUnits(BigDecimal price) {
        try {
            return price.setScale(2, RoundingMode.UNNECESSARY)
                    .movePointRight(2)
                    .longValueExact();
        } catch (ArithmeticException ex) {
            throw invalidCheckout("Product prices must have at most two decimal places");
        }
    }

    private static long addAmounts(long total, long amountMinor) {
        try {
            return Math.addExact(total, amountMinor);
        } catch (ArithmeticException ex) {
            throw invalidCheckout("The checkout total is too large");
        }
    }

    private static void validateGatewaySession(CheckoutGatewaySession session) {
        if (session == null
                || session.providerSessionId() == null
                || session.providerSessionId().isBlank()
                || session.providerSessionId().length() > 255
                || (session.checkoutUrl() != null && session.checkoutUrl().length() > 2048)) {
            throw new CommerceException(
                    HttpStatus.BAD_GATEWAY,
                    "The payment provider returned an invalid checkout session"
            );
        }
    }

    private static String fingerprint(List<UUID> productIds) {
        String canonical = productIds.stream()
                .map(UUID::toString)
                .sorted()
                .reduce((left, right) -> left + "," + right)
                .orElseThrow();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(canonical.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is unavailable", ex);
        }
    }

    private void expireIfNecessary(CommerceOrder order) {
        if (order.getStatus() == CommerceOrderStatus.PENDING
                && order.getExpiresAt().isBefore(Instant.now())) {
            order.setStatus(CommerceOrderStatus.EXPIRED);
            paymentAttemptRepository.findByOrderId(order.getId()).ifPresent(attempt -> {
                attempt.setStatus(PaymentAttemptStatus.EXPIRED);
                paymentAttemptRepository.save(attempt);
            });
            orderRepository.save(order);
        }
    }

    private static CommerceException invalidCheckout(String message) {
        return new CommerceException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

import { ProductMinimised, AppDispatch } from 'core/api/models';
import { Button } from '@shared/ui';
import { selectAuthUser } from 'core/store/auth-store';
import {
  selectAllShopCartProducts,
  selectShopCartTotal,
  removeProductFromCart,
  moveCartItemToWishlist,
  clearShoppingCart,
} from 'core/store/shop-cart';
import { selectWishlistIds } from 'core/store/wishlist';
import { enrollInFreeProductAPI } from 'core/api/services';
import {
  formatCommerceAmount,
  getCartCheckoutKind,
  getCommerceErrorMessage,
  isSuccessfulOrderStatus,
  isTerminalUnsuccessfulOrderStatus,
  startPaidCheckout,
  validatePaidCart,
} from './cart-checkout.utils';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../assets/image-placeholder.png');

import './cart.styles.scss';

const Cart: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartProducts = useSelector(selectAllShopCartProducts);
  const cartTotal = useSelector(selectShopCartTotal);
  const wishlistIds = useSelector(selectWishlistIds);
  const [checkingOut, setCheckingOut] = useState(false);
  const cartCheckoutKind = getCartCheckoutKind(cartProducts);
  const containsPaidProducts = cartCheckoutKind === 'PAID';
  const containsMixedProducts = cartCheckoutKind === 'MIXED';

  const handleRemoveFromCart = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(removeProductFromCart(prod.id));
    }
  };

  const handleMoveToWishlist = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(moveCartItemToWishlist(prod.id));
    }
  };

  const handleFreeCheckout = async () => {
    const productIds = cartProducts
      .map((product) => product.id)
      .filter((id): id is string => Boolean(id));
    if (productIds.length === 0 || containsPaidProducts) {
      return;
    }

    setCheckingOut(true);
    try {
      await Promise.all(productIds.map(enrollInFreeProductAPI));
      dispatch(clearShoppingCart());
      toast.success('Products added to your library');
      navigate('/app/library/all-products');
    } catch {
      toast.error('The free products could not be added to your library.');
    } finally {
      setCheckingOut(false);
    }
  };

  const handlePaidCheckout = async () => {
    const validation = validatePaidCart(cartProducts, user?.id);
    if (!validation.valid) {
      toast.error(validation.message);
      return;
    }

    setCheckingOut(true);
    try {
      const { session, order } = await startPaidCheckout(cartProducts);

      if (session.checkoutUrl) {
        return;
      }

      if (!order) {
        toast.info('Checkout started. Your cart has been saved.');
        return;
      }

      const amount = formatCommerceAmount(order.totalMinor, order.currency);

      if (isSuccessfulOrderStatus(order.status)) {
        dispatch(clearShoppingCart());
        toast.success(
          amount
            ? `Payment confirmed for ${amount}. Products added to your library.`
            : 'Payment confirmed. Products added to your library.',
        );
        navigate('/app/library/all-products');
        return;
      }

      if (order.status === 'PENDING') {
        toast.info('Payment is still pending. Your cart has been saved.');
        return;
      }

      if (isTerminalUnsuccessfulOrderStatus(order.status)) {
        toast.error('Payment was not completed. Your cart has been saved.');
      }
    } catch (error) {
      toast.error(getCommerceErrorMessage(error));
    } finally {
      setCheckingOut(false);
    }
  };

  const handleCheckout = () => {
    if (containsMixedProducts) {
      toast.error(
        'Free and paid products cannot be checked out together. Please split your cart.',
      );
      return;
    }

    if (containsPaidProducts) {
      void handlePaidCheckout();
      return;
    }

    void handleFreeCheckout();
  };

  return (
    <div className="cart-page">
      <h1 className="cart-page-title">Shopping Cart</h1>
      {cartProducts.length > 0 ? (
        <>
          <section className="cart-container">
            <div className="cart-container-line">
              <p>{cartProducts.length} products in your cart</p>
              <hr className="cart-underline"></hr>
            </div>
            <article className="cart-products-container">
              <div className="cart-products-list">
                {cartProducts.map((prod) => {
                  const isInWishlist = wishlistIds.has(prod.id);
                  const productTitle = prod.title ?? 'Untitled product';

                  return (
                    <div key={prod.id} className="cart-product">
                      <img
                        src={placeholderImage}
                        alt={productTitle}
                        className="product-card-image"
                      />
                      <div className="cart-product-details">
                        <h3>{productTitle}</h3>
                        <p>By {prod.createdByName}</p>
                        <p>4.7 ⭐⭐⭐⭐⭐ (32,025 ratings)</p>
                      </div>
                      <div className="cart-product-actions">
                        <button
                          type="button"
                          onClick={() => handleRemoveFromCart(prod)}
                        >
                          Remove
                        </button>
                        <button
                          type="button"
                          disabled={isInWishlist}
                          onClick={() => handleMoveToWishlist(prod)}
                        >
                          Move to wishlist
                        </button>
                      </div>
                      <div className="cart-product-price-tag">
                        €{prod.price}
                      </div>
                    </div>
                  );
                })}
              </div>
            </article>
            <aside className="cart-products-aside">
              <h4>Total:</h4>
              <h2>
                {cartTotal && cartTotal > 0 ? (
                  <span>€{cartTotal}</span>
                ) : (
                  <span>free</span>
                )}
              </h2>
              {containsPaidProducts && (
                <p className="cart-products-aside__notice" role="note">
                  Test payment — No real charge will be made during checkout.
                </p>
              )}

              <Button
                type="button"
                variant="primary"
                disabled={checkingOut}
                onClick={handleCheckout}
              >
                {checkingOut ? 'Processing...' : 'Proceed to checkout'}
              </Button>
              {containsMixedProducts && (
                <p role="alert" className="cart-products-aside__message">
                  Free and paid products cannot be checked out together. Please
                  split your cart.
                </p>
              )}
            </aside>
          </section>
        </>
      ) : (
        <p>You don&apos;t have any products in your shopping cart</p>
      )}
      <div className="cart-page-bottom">
        <h2>You might also like</h2>
      </div>
    </div>
  );
};

export default Cart;

import { AxiosError } from 'axios';

import {
  CommerceCheckoutSession,
  CommerceOrder,
  CommerceOrderStatus,
  ProductMinimised,
} from 'core/api/models';
import {
  createCommerceCheckoutSessionAPI,
  getCommerceOrderAPI,
} from 'core/api/services';

const IDEMPOTENCY_STORAGE_KEY = 'commerceCheckout:idempotency:v1';
const IDEMPOTENCY_TTL_MS = 30 * 60 * 1000;
const MAX_CHECKOUT_PRODUCTS = 20;

interface StoredIdempotency {
  cartSignature: string;
  key: string;
  createdAt: number;
}

export type CartCheckoutKind = 'FREE' | 'PAID' | 'MIXED' | 'EMPTY';

export interface CartValidationResult {
  valid: boolean;
  message?: string;
}

export interface PaidCheckoutResult {
  session: CommerceCheckoutSession;
  order?: CommerceOrder;
}

export const getProductPriceAmount = (product: ProductMinimised): number => {
  if (product.price === 'free' || product.price === null || product.price === undefined) {
    return 0;
  }

  return Number(product.price) || 0;
};

export const getCartCheckoutKind = (
  products: ProductMinimised[],
): CartCheckoutKind => {
  if (products.length === 0) {
    return 'EMPTY';
  }

  const freeCount = products.filter(
    (product) => getProductPriceAmount(product) === 0,
  ).length;

  if (freeCount === products.length) {
    return 'FREE';
  }

  if (freeCount === 0) {
    return 'PAID';
  }

  return 'MIXED';
};

export const formatCommerceAmount = (
  totalMinor?: number,
  currency = 'EUR',
): string | null => {
  if (typeof totalMinor !== 'number') {
    return null;
  }

  return new Intl.NumberFormat(undefined, {
    style: 'currency',
    currency,
  }).format(totalMinor / 100);
};

export const validatePaidCart = (
  products: ProductMinimised[],
  buyerId?: string,
): CartValidationResult => {
  if (products.length === 0) {
    return { valid: false, message: 'Your cart is empty.' };
  }

  if (products.length > MAX_CHECKOUT_PRODUCTS) {
    return {
      valid: false,
      message: 'Checkout supports up to 20 products at a time.',
    };
  }

  if (getCartCheckoutKind(products) === 'MIXED') {
    return {
      valid: false,
      message:
        'Free and paid products cannot be checked out together. Please split your cart.',
    };
  }

  if (products.some((product) => getProductPriceAmount(product) === 0)) {
    return {
      valid: false,
      message: 'Free products use free enrollment and cannot enter paid checkout.',
    };
  }

  if (products.some((product) => product.type === 'MEMBERSHIP')) {
    return {
      valid: false,
      message: 'Membership checkout is not available yet.',
    };
  }

  const productIds = products
    .map((product) => product.id)
    .filter((id): id is string => Boolean(id));

  if (productIds.length !== products.length) {
    return {
      valid: false,
      message: 'One or more cart products cannot be checked out yet.',
    };
  }

  if (new Set(productIds).size !== productIds.length) {
    return {
      valid: false,
      message: 'Duplicate products cannot be checked out together.',
    };
  }

  const creatorIds = products
    .map((product) => product.createdById)
    .filter((id): id is string => Boolean(id));

  if (creatorIds.length === products.length && new Set(creatorIds).size > 1) {
    return {
      valid: false,
      message: 'Products from different Creators cannot be checked out together.',
    };
  }

  if (
    buyerId &&
    products.some((product) => product.createdById && product.createdById === buyerId)
  ) {
    return {
      valid: false,
      message: 'You cannot buy your own product.',
    };
  }

  if (
    products.some(
      (product) => product.status && product.status !== 'PUBLISHED',
    )
  ) {
    return {
      valid: false,
      message: 'Only published products can be checked out.',
    };
  }

  return { valid: true };
};

export const getPaidProductIds = (products: ProductMinimised[]): string[] =>
  products
    .filter((product) => getProductPriceAmount(product) > 0)
    .map((product) => product.id)
    .filter((id): id is string => Boolean(id));

export const getCartSignature = (productIds: string[]): string =>
  [...productIds].sort().join('|');

const readStoredIdempotency = (): StoredIdempotency | null => {
  try {
    if (typeof window === 'undefined') {
      return null;
    }

    const raw = window.sessionStorage.getItem(IDEMPOTENCY_STORAGE_KEY);
    return raw ? (JSON.parse(raw) as StoredIdempotency) : null;
  } catch {
    return null;
  }
};

const writeStoredIdempotency = (entry: StoredIdempotency) => {
  try {
    if (typeof window === 'undefined') {
      return;
    }

    window.sessionStorage.setItem(
      IDEMPOTENCY_STORAGE_KEY,
      JSON.stringify(entry),
    );
  } catch {
    /* ignore storage errors */
  }
};

export const getIdempotencyKeyForCart = (
  productIds: string[],
  now = Date.now(),
): string => {
  const cartSignature = getCartSignature(productIds);
  const existing = readStoredIdempotency();

  if (
    existing?.cartSignature === cartSignature &&
    now - existing.createdAt < IDEMPOTENCY_TTL_MS
  ) {
    return existing.key;
  }

  const key = crypto.randomUUID();
  writeStoredIdempotency({ cartSignature, key, createdAt: now });

  return key;
};

export const getCommerceErrorMessage = (error: unknown): string => {
  const status = (error as AxiosError)?.response?.status;

  switch (status) {
  case 400:
    return 'Checkout could not start. Please try again.';
  case 409:
    return 'Checkout could not continue because this cart changed or includes a product you already own.';
  case 422:
    return 'This cart cannot be checked out. Please review the products and try again.';
  case 503:
    return 'Payments are not configured right now. Please try again later.';
  default:
    return 'Checkout could not be started. Please try again.';
  }
};

export const isSuccessfulOrderStatus = (status: CommerceOrderStatus) =>
  status === 'PAID';

export const isTerminalUnsuccessfulOrderStatus = (
  status: CommerceOrderStatus,
) => status === 'FAILED' || status === 'EXPIRED' || status === 'REFUNDED';

export const startPaidCheckout = async (
  products: ProductMinimised[],
): Promise<PaidCheckoutResult> => {
  const productIds = getPaidProductIds(products);
  const idempotencyKey = getIdempotencyKeyForCart(productIds);
  const session = await createCommerceCheckoutSessionAPI(
    productIds,
    idempotencyKey,
  );

  if (session.checkoutUrl) {
    window.location.assign(session.checkoutUrl);
    return { session };
  }

  if (!session.orderId) {
    return { session };
  }

  const order = await getCommerceOrderAPI(session.orderId);
  return { session, order };
};

